window.REGIONAL_ORIGINS={"regions":{"rhodes":{"id":"rhodes","intro":"罗德岛既是一艘拥有旧文明来历的舰船，也是后来形成的医疗组织。舰体、凯尔希的使命与巴别塔的理念来自不同年代，不能用同一个成立年份概括；组织前史须先说明这些部分如何逐渐相遇。","scope":"从旧文明舰船与AMa-10计划，写至凯尔希的古代行旅、899年的形态变化及1031年前后巴别塔的形成；后接舰上人员、阿米娅和博士的经历。","chronologyNote":"旧文明使用的TT日期不换算为泰拉历。AMa-10起源、舰体来历与医疗组织成立是不同事件；899年、1031年有直接记录，正式挂牌日期与舰船最初制造年份未获本篇材料明确说明。","periods":[{"id":"rhodes-ancient-vessel","period":"旧文明末期，早于现行泰拉纪年","title":"旧文明舰船与AMa-10项目","body":"如今被称为罗德岛的舰船，在现有泰拉诸国形成以前已经存在。Mon3tr保存的记录说明，舰船曾在群星间航行，两位管理员在其中观察黑暗潮汐，并讨论未来。AMa-10机械生命项目也在这艘船上进行，以双生循环系统为核心，希望制造能适应极端环境、参与改造自然和建设家园的机械生命。计划原本设想百万级量产，却没有等到量产实现，潮汐余波已经抵达，留下一个特殊个体。\n\n这一记录能够说明舰体与旧时代科学工程的关系，但不能由此认定当时已经存在以矿石病治疗为业的罗德岛制药。舰船是遗留下来的设施，后来的组织是新的历史主体。预言家和普瑞赛斯对AMa-10的期待也不仅限于执行工程任务，他们为其挑选准备导入的诗歌，讨论在文明毁灭之后如何向后来者说明生命的价值。后来凯尔希与Mon3tr的行动，正建立在这些被保存的知识、指令和未完成的问题之上。","people":["博士","普瑞赛斯","凯尔希","Mon3tr"],"refs":[{"label":"Mon3tr·档案资料四","url":"https://prts.wiki/w/Mon3tr#档案资料","evidence":"game","note":"依据本地官方handbook对应条目核对，链接为游戏档案展示页。"},{"label":"《相变临界》17-18 · 行动前〈灵魂悄然〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_main_17-17_beg.txt","evidence":"game","note":"仅取开篇旧文明回忆，不把第十七章当前年份前移。"}]},{"id":"rhodes-kaltsit-mission","period":"预言家休眠以后，历经漫长古代","title":"寻找生命与守护文明的行旅","body":"预言家曾从休眠中醒来，由AMa-10陪同勘察泰拉。彼时各种计划尚未达到预期，他在衰老和长期孤独中继续观察，最后再次回到石棺，要求同行的造物寻找生命的痕迹、寻找自身的答案。此后它独自出发，逐渐成为后来被称为凯尔希的存在。这里的出发早于任何巴别塔组织，也不是一次现代医疗企业的远征。\n\n她在北方发现生命活动，与尚不能充分理解其使命的鸟类共同旅行，又见证不同部族为古代遗迹争斗直至毁灭。她考虑刻下知识、引导后来者学习，却发现有限空间无法容纳全部文明经验，最终重新掩埋遗迹。在这些经历中，保护文明逐渐不再只是抽象指令，也涉及对具体生命、误解和死亡的回应。后来的医疗合作承接了这段经验，但不能把她早期每一次介入都解释为已经制定好的巴别塔计划。","people":["博士","凯尔希","Mon3tr"],"refs":[{"label":"《相变临界》17-18 · 行动前〈灵魂悄然〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_main_17-17_beg.txt","evidence":"game"},{"label":"Mon3tr·档案资料四","url":"https://prts.wiki/w/Mon3tr#档案资料","evidence":"game","note":"依据本地官方handbook对应条目核对，链接为游戏档案展示页。"}]},{"id":"rhodes-899-alliance","period":"899年及其后的卡兹戴尔时期","title":"凯尔希重塑与萨卡兹盟友出现","body":"Mon3tr的899年3月1日记录，为后来合作提供了一个可直接核对的节点。凯尔希经历第二次死亡后重新获得身体，开始选择与普通泰拉生命更接近的形态。Mon3tr注意到，她此前已经模仿泰拉人改变外观，此时又放弃部分旧有力量；她与Mon3tr之间的分工因而更明确，一方更多通过交谈进入社会，另一方承担保护和直接战斗。\n\n记录同时提到一位曾为敌人的萨卡兹女性，凯尔希开始给予她罕见的信任。结合主线对特蕾西娅身边重生的回忆，这段关系并非从毫无冲突的合作开始，而是在毁城战争的后果中转变。特蕾西娅及幸存者正在寻找重建城市与改变生活的办法，凯尔希则带来其他文明和源石问题的知识。具体协议的签署日期未在这些材料中列明，但从相互对立到共同工作的关系变化，早于后来舰上的巴别塔成员集结。","people":["凯尔希","Mon3tr","特蕾西娅","特雷西斯"],"refs":[{"label":"Mon3tr·档案资料四","url":"https://prts.wiki/w/Mon3tr#档案资料","evidence":"game","note":"依据本地官方handbook对应条目核对，链接为游戏档案展示页。"},{"label":"《淬火尘霾》11-17 · 行动前〈回答我〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_main_11-15_beg.txt","evidence":"game"},{"label":"《慈悲灯塔》14-8 · 行动后〈抵近支援作战〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_main_14-07_end.txt","evidence":"game"}]},{"id":"rhodes-babel-early-services","period":"1031年前后，舰上巴别塔阶段以前","title":"巴别塔早期的学校与对外合作","body":"1031年的明确记录中，巴别塔已经在卡兹戴尔设立办事处、组织医疗人员，并建设学校。特蕾西娅关心学校能否运作，凯尔希负责安顿来自不同国家和种族的同事；他们又与萨尔贡、雷姆必拓的关系人接洽，同哥伦比亚科学家讨论技术交换，以萨卡兹古老巫术研究换取移动农场等建设条件。这一阶段的工作地点首先是卡兹戴尔城内，不能把后来所有舰上设施都提前放到这里。\n\n军事委员会与巴别塔此时尚处于共同支持重建的框架下，特雷西斯承诺安排人员保护巴别塔，特蕾西娅则希望借一座城的教育、医疗和跨族群协作，推动萨卡兹与其他地区建立不同关系。成员遭到偏见、学校无人来上课等问题，后来暴露这种安排的脆弱，但医疗与教育的方向已经明确。后篇将继续讲述它在冲突中转到舰船生活，以及博士、阿米娅和各支行动人员如何加入；这些属于组织演变，不是舰体最初诞生的年代。","people":["特蕾西娅","凯尔希","特雷西斯","阿斯卡纶"],"refs":[{"label":"《巴别塔》BB-1 · 行动后〈宏伟愿景〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act33side/level_act33side_01_end.txt","evidence":"game"},{"label":"《巴别塔》BB-2 · 行动后〈命途何在〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act33side/level_act33side_02_end.txt","evidence":"game"}]}]},"ursus":{"id":"ursus","intro":"乌萨斯帝国形成于推翻骏鹰统治的战争，其后长期依赖军队、贵族领地与扩张维持国家秩序。切尔诺伯格事变以前，皇帝与旧军功集团的权力冲突、感染者劳役和地方管制已经持续多年。","scope":"从骏鹰时期、31年的政权更替，写至近代扩张、大叛乱及其制度余波；后接切尔诺伯格学生经历。","chronologyNote":"31年见于主线第十六章的明确历史追述；骏鹰王国的建国年、本篇未能直接核实的战争年份不予补写。引用后续章节只为核实其追述的前史，不把当前事件移到早年。","periods":[{"id":"ursus-hippogryph-rule","period":"乌萨斯建国以前，确切起始年未明","title":"骏鹰统治与北方旧王国","body":"乌萨斯成为国家以前，北方存在骏鹰王国。后世乌萨斯人的叙述把这一时代记为被奴役的过去：骏鹰掌握统治权，乌萨斯等族群承担劳动和战争。科西切借这种统治关系向塔露拉灌输强者支配弱者的观念，后来学生和矿工则以反抗旧压迫作为讨论现实制度的历史依据。相同的历史在不同人手中服务于不同政治主张，不能把其中一人的评价当成完整的王国编年史。\n\n凯尔希的回忆另保存了一位骏鹰国王的片段。他自述曾征服土地、积累粮食与财富，却仍困惑于生命的意义，最终进入石棺，离开时恢复为古老的有翼生命形态。这个场景确认了骏鹰统治者与北方古代遗迹的联系，却没有给出该王的姓名、登基年或他与末代王权的关系。因此，骏鹰王国的起源在本篇仍保留年代边界。","people":["凯尔希","塔露拉"],"refs":[{"label":"《怒号光明》R8-5 · 行动后〈寒冷，来自知觉〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_main_08-05_end.txt","evidence":"game"},{"label":"《相变临界》17-18 · 行动前〈灵魂悄然〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_main_17-17_beg.txt","evidence":"game","note":"只取骏鹰国王的古代回忆，不用当前章节发生年为其定年。"},{"label":"《人们，我们》PA-4 · 行动后〈一墙之隔〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act51side/level_act51side_04_end.txt","evidence":"game"}]},{"id":"ursus-igor-foundation","period":"31年及其后的建国记忆","title":"伊戈尔起义与帝国建立","body":"伊戈尔原本出身军旅行伍。起义使他与追随者成为新政权的建立者，后世把他尊为乌萨斯的开国皇帝。主线记述，31年冬，他在涅瓦湖击败守卫圣骏堡的最后一支军队，骏鹰王国随之覆灭。帝国以推翻压迫者的胜利建立自身的政治记忆，跟随伊戈尔征战的十六名将领也成为后来贵族家系强调荣耀血统的重要来源。\n\n这场政权更替并非只有单一族群间的彻底清除。尼克托讲述的史料争论指出，伊戈尔曾与骏鹰贵族米哈伊尔并肩作战，并通过协议让渡部分权力，换取一些旧贵族支持。约150年时，有剧作家因表现这种妥协而遭谴责，直到协议原件重现，其叙述才得到印证。新帝国既继承了反抗的荣誉，也吸收了部分旧统治力量；后来的纯粹英雄叙事遮蔽了这层建国条件。","people":[],"refs":[{"label":"《反常光谱》16-14 · 行动前〈唯有坦途〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_main_16-14_beg.txt","evidence":"game"},{"label":"《人们，我们》PA-4 · 行动后〈一墙之隔〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act51side/level_act51side_04_end.txt","evidence":"game"},{"label":"《人们，我们》PA-6 · 行动后〈各自流亡〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act51side/level_act51side_06_end.txt","evidence":"game"}]},{"id":"ursus-expansion-estates","period":"近代先皇统治时期","title":"对外扩张与军功贵族壮大","body":"近代乌萨斯持续对外扩张，军队将领与贵族在战争中获得城市、居民和资源，军事权力因而与地方利益紧密结合。塔露拉向同伴解释大叛乱时，特别指出，后来举兵的贵族将领正是在这一时代受益最多的人。皇权并非在一张统一的行政网络上直接管理全部社会，握有军队和领地的集团能够把战果转为自己的权势。\n\n温迪戈战士博卓卡斯替曾为乌萨斯服役，赫拉格也在其军队中度过多年；这些外族军人说明帝国的军事体系并不只依赖乌萨斯一族。与此同时，血峰战役的失败成为后世反复提及的挫折。费奥多尔明确斥责将领把那场惨败装饰为光荣，认为他们仍沉醉于先皇时代的扩张想象。这些追述可以确认旧军功集团形成的背景与战争受挫的事实，但不足以在此补全每次远征、工业扩建和皇位继承的精确年表。","people":["爱国者","赫拉格","费奥多尔","塔露拉"],"refs":[{"label":"《怒号光明》R8-5 · 行动前〈寒冷，来自知觉〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_main_08-05_beg.txt","evidence":"game"},{"label":"《苦难摇篮》7-10 · 行动后〈暗淡者之火〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_main_07-08_end.txt","evidence":"game"},{"label":"《相变临界》17-9 · 行动前〈永不祈祷〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_main_17-08_beg.txt","evidence":"game"}]},{"id":"ursus-rebellion-aftermath","period":"费奥多尔即位后至切尔诺伯格事变以前","title":"大叛乱与感染者管制扩张","body":"新皇登基后试图收回旧将领控制的资源、城市与人口，既得利益者的反抗最终发展为大叛乱。战争不仅是皇帝与贵族之间的对抗，保皇派同样借打击敌对家族重新分配利益，一些在战中升迁的年轻军官也未必忠于改革。叛乱结束后，旧贵族与集团军的力量受到削弱，帝国议会逐渐蚕食其地位，却没有让这些势力从此消失。\n\n战乱还改变了感染者的处境。塔露拉追述，大叛乱以后组织起来搜捕感染者的纠察队，后来成为横行乡野的地方强权，借搜查侵占村庄的收成。爱国者的儿子曾为感染者权益奔走，父子关系与军旅生活也在这一时期走向破裂；爱国者最终带着一支部队离开帝国。搜捕、矿场劳役和被迫迁徙由此成为早于切城事变的持续问题，冻原上的互助聚落与游击队正是在这种处境中发展起来。","people":["费奥多尔","维特","爱国者","塔露拉","霜星"],"refs":[{"label":"《怒号光明》R8-5 · 行动前〈寒冷，来自知觉〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_main_08-05_beg.txt","evidence":"game"},{"label":"《苦难摇篮》7-7 · 幕间〈26:37:14〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_st_07-02.txt","evidence":"game"},{"label":"《局部坏死》6-13 · 幕间〈没有火,没有光〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_st_06-02.txt","evidence":"game"},{"label":"《苦难摇篮》7-10 · 行动后〈暗淡者之火〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_main_07-08_end.txt","evidence":"game"}]}]},"lungmen":{"id":"lungmen","intro":"龙门的古代建城年表并未在本篇所核资料中完整公开，能够直接追踪的是魏彦吾等人经营城市、抵御外部干涉以及形成近卫局与下城区秩序的过程。陈返乡任职时，这些治理安排已经先于她存在。","scope":"从可考的近代城市建设与炎国关系，写至科西切干涉、塔露拉离开及下城区治理格局，止于陈推动警务改革的起点。","chronologyNote":"不把魏彦吾口中的共同建设自动认定为古代首次建城。爱德华死亡为主线明确的约二十年前；下城区制度形成与外部冲突的部分时段可能交叠，具体设立日未明。","periods":[{"id":"lungmen-city-building","period":"魏彦吾经营龙门的早期，确切建城年未明","title":"近代城市建设与炎国行政关系","body":"魏彦吾后来谈及龙门时，把它称为自己与伙伴亲手建设、许多人共同生活的家。这能确认他与文月、林舸瑞等人的长期经营，却不等于龙门此前完全不存在，也不足以推出一个精确建城年。城市已有总督、近卫局及商业力量参与日常运作，外来居民、商人和底层街区不断进入同一套城市生活，政治领导与具体经营需要同时面对这些不同群体。\n\n龙门属于炎国的重要城市，魏彦吾在重大安全与外交问题上受到中央关系约束。主线中，他明确知道皇帝不会允许自己擅自对乌萨斯开战；监察力量进入时，地方行动也会面临审查。这说明总督拥有很强的地方处置能力，并不等于龙门是可以自行宣战的独立国家。近代建设能够不断推进，既依靠城市内部的权力协作，也依靠在炎国与周边国家之间维持空间。后来的国际物流与投资活动，应放在这个城市行政背景中理解。","people":["魏彦吾","文月","鼠王"],"refs":[{"label":"《相见欢》OR-ST-2 · 幕间〈雷公栗〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act40side/level_act40side_st02.txt","evidence":"game","note":"只取对过去共同建设的回顾。"},{"label":"《苦难摇篮》7-2 · 行动后〈别离之夜〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_main_07-01_end.txt","evidence":"game"},{"label":"《苦难摇篮》7-3 · 行动后〈变节之刃〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_main_07-02_end.txt","evidence":"game"}]},{"id":"lungmen-koschei-crisis","period":"主线前约二十年及塔露拉幼年","title":"科西切干涉与塔露拉离城","body":"科西切曾深入龙门的权力冲突，魏彦吾与爱德华·雅特利亚斯一度共同对抗他，并将其逐出城市。塔露拉后来反驳科西切时明确指出，他曾隐瞒双方的合作，把魏彦吾描绘为杀父事件中单独的主谋。可以确认，爱德华约在主线二十年前死于龙门，而他的死亡卷入了红龙家系、魏彦吾的选择与科西切的操纵，不能用黑蛇向孩子灌输的版本代替全部经过。\n\n科西切又把塔露拉带离龙门，并借国际交涉的边界阻止追击。影卫提出越境夺回女孩时，魏彦吾判断，莱塔尼亚新登基女皇派出的代表与随行武装就在附近，强行动手可能被科西切利用，引爆对龙门乃至炎国不利的外交冲突，于是没有追入。幼年的陈未能与塔露拉一同离开，这成为姐妹分离的节点。城市在危机中得以继续存在，却也把无法解决的家庭损失留给了下一代。","people":["魏彦吾","科西切","塔露拉","陈","文月"],"refs":[{"label":"《苦难摇篮》7-3 · 行动后〈变节之刃〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_main_07-02_end.txt","evidence":"game"},{"label":"《怒号光明》R8-5 · 行动后〈寒冷，来自知觉〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_main_08-05_end.txt","evidence":"game"},{"label":"《怒号光明》M8-2 · 幕间〈失语，产自多言〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_st_08-02.txt","evidence":"game"}]},{"id":"lungmen-lower-district-order","period":"长期城市经营形成的格局，陈返乡任职以前已存在","title":"贫民区建立与正式秩序并存","body":"龙门的下城区不是一个与城市完全无关的空白地带。林雨霞在档案中说明，父亲建立贫民区的初衷，是让它成为城市的缓冲与保护层；诗怀雅也确认，这一缓冲社区是林舸瑞长期经营的成果。鼠王的名字在这里代表一种秩序，处理黑道、街区和居民之间的关系，近卫局则承担公开警务。两者有合作，却并非完全相同的机构，也不总以同一方法面对问题。\n\n这种安排容纳了感染者与许多难以进入繁荣街区的人，同时保留了贫困、灰色产业和难以公开处理的矛盾。林雨霞指出，感染者问题是贫民区的主要问题之一，却不是全部；有人希望缓冲社区成为生活空间，也有人试图让它变成没有出口的封闭区域。鼠王在与外来帮派交涉时，又强调龙门有律宪、自己有规矩，物流企业也有各自准则，说明城市并不是由一份黑道规则单独统治。陈回城以后面对的，正是这套已经运作多年的分层秩序，后篇的警务改革由此展开。","people":["鼠王","林","诗怀雅","陈"],"refs":[{"label":"林·档案资料四","url":"https://prts.wiki/w/%E6%9E%97#档案资料","evidence":"game","note":"依据本地官方handbook对应条目核对，链接为游戏档案展示页。"},{"label":"《局部坏死》6-5 · 行动后〈解决谁？〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_main_06-05_end.txt","evidence":"game"},{"label":"《喧闹法则》CB-EX2 · 行动后〈南辕北辙〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act5d0/level_act5d0_ex02_end.txt","evidence":"game","note":"只取对既有律宪与规矩的说明，不提前叙述安魂夜事件结果。"}]}]},"victoria":{"id":"victoria","intro":"维多利亚并非从阿斯兰王室开始。德拉克的早期统治、塔拉被纳入王权、阿斯兰崛起及近代扩张，共同形成了王冠、贵族领地与地方认同交错的帝国，后篇的王室覆亡只是这条历史链上的一次转折。","scope":"从德拉克与塔拉的早期关系，写至阿斯兰取得王权、四国战争及末代国王面临的制度压力；不重写后篇的处决与首都争夺。","chronologyNote":"古老盖尔王故事同时存在传说和政治解释，刺杀责任不作定论。阿斯兰崛起在不同人物追述中使用“两百多年前”与“三百多年前”的近似时距，本篇统一保留为数百年前，不强行合成年份。","periods":[{"id":"victoria-draco-tara","period":"千年前及其后的德拉克统治时期","title":"德拉克王权与塔拉从属关系","body":"维多利亚早期由德拉克掌握土地与王权，塔拉则保留着另一组有关游牧氏族和红龙统治者的传统。苇草所读的传说称，一位德拉克率盖尔氏族南迁，在塔拉建立生活；此后维多利亚的红龙杀死塔拉最后的游牧首领，把盖尔王的头衔授予其幼子，塔拉统治者由此被限制在宫廷之内。这里的具体人物和行为出自传说，不能把全部细节当作已完成考据的编年史。\n\n苇草后来公开回顾历史时，仍将千年前的维多利亚进犯与盖尔王头衔的形成联系起来，又提到六百多年前，塔拉王城被迫接受维多利亚制度与生活方式。可以确认的是，塔拉的从属并非阿斯兰时代才开始：红龙之间也曾存在征服和依附。后来的塔拉认同因此既继承德拉克王朝象征，也包含对历次外来统治的反抗，不能简化为同一王族从来没有内部分歧。","people":["苇草"],"refs":[{"label":"《照我以火》FC-8 · 行动前〈她的影子〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act22side/level_act22side_08_beg.txt","evidence":"game"},{"label":"《挽歌燃烧殆尽》EA-ST-3 · 幕间〈封底纪事〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act41side/level_act41side_st03.txt","evidence":"game","note":"只取苇草对千年前和六百多年前的回顾，不前移当时的政治结局。"}]},{"id":"victoria-aslan-settlement","period":"数百年前至德拉克王统失势","title":"阿斯兰崛起与王位分享协议","body":"来自萨尔贡的阿斯兰在维多利亚兴起，经过与德拉克的战争取得统治地位。两族曾签订休战与分享王位的协议，成为后世维多利亚王权的法理来源。诸王之息既曾斩下红龙首级，又曾被两族君王共同握持言和；首都保留阿斯兰与德拉克君主的塑像，圣王会建筑也以两族共建和平作为纪念对象。战争和和解同时留在国家象征中。\n\n塔拉记忆对这段安排的评价并不一致。诗人西莫提到最后盖尔王签下和平协议、销熔兵器，随后遭臣下刺杀的传说；沃里克则坚持阿斯兰应承担阴谋责任，但他没有在对话中拿出足以确定凶手的证据。其后德拉克离开王城、塔拉失去自己的统治者，王位长期由阿斯兰掌握，成为后来不满的来源。协议确实存在，不代表约定的权力分享始终得到实行；同样，后世政治人物的怀疑也不能直接替代刺杀案的事实结论。","people":["苇草","推进之王"],"refs":[{"label":"《风暴瞭望》9-13 · 行动后〈战地救援〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_main_09-11_end.txt","evidence":"game"},{"label":"《慈悲灯塔》14-7 · 行动后〈执行反制作战〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_main_14-06_end.txt","evidence":"game"},{"label":"《照我以火》FC-3 · 行动前〈引燃草垛〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act22side/level_act22side_03_beg.txt","evidence":"game"},{"label":"《雪山降临1101》OS-6 · 行动前〈绿翡翠〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act46side/level_act46side_06_beg.txt","evidence":"game"}]},{"id":"victoria-industrial-expansion","period":"近代扩张与四国战争时期","title":"工业扩张与对高卢战争","body":"近代维多利亚的力量向境外延伸，其中一条可直接追踪的路线通往雷姆必拓。早期经营蒸汽技术的商人向当地总工会取得有限采矿许可，运回矿石建立工厂，积累财富并进入权贵阶层，还在商道之间建设小型移动城市。工业、矿产供给与新贵族的兴起在这条记录中相互联系，远方矿区也逐渐卷入维多利亚内部的利益分配。\n\n在核心圈大战中，乌萨斯与维多利亚加入对高卢的战争，四皇会战成为维多利亚官方教育反复表彰的胜利。弗雷德里克三世因此以征服高卢的君主形象进入王室记忆。胜利的另一面是高卢居民承受的毁灭，风笛在军旅经历中也明确意识到，两种记忆并不相同。战后王室并未因胜利而摆脱负担，阿勒黛追述，战争债务仍压在帝国身上；高卢的覆亡和胜利者后来的财政困境，应作为同一场战争不同层面的后果理解。","people":["风笛","推进之王"],"refs":[{"label":"莱恩哈特·档案资料二","url":"https://prts.wiki/w/%E8%8E%B1%E6%81%A9%E5%93%88%E7%89%B9#档案资料","evidence":"game","note":"依据本地官方handbook对应条目核对，链接为游戏档案展示页。"},{"label":"《巴别塔》BB-1 · 行动前〈宏伟愿景〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act33side/level_act33side_01_beg.txt","evidence":"game"},{"label":"《风暴瞭望》9-18 · 行动后〈“破晓”〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_main_09-16_end.txt","evidence":"game"},{"label":"《淬火尘霾》11-16 · 行动后〈荣光猎场〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_main_11-14_end.txt","evidence":"game"}]},{"id":"victoria-crown-dukes","period":"阿利斯泰尔在位后期，王室覆亡以前","title":"王室债务与贵族权力积累","body":"阿利斯泰尔继承的并不是一个没有争议的王位。王室需要承担近代战争债务，已经衰微的德拉克仍不愿接受阿斯兰越来越长的统治，国王因而同时面对现实财政和王位法理的压力。祖辈的战功并没有自动变成他能够支配的资源，保留在王陵中的未完成塑像，也反映出这段统治结束得异常突然。后篇将从国王被处死和维娜逃离王室的阶段继续叙述。\n\n贵族的经济与行政权力在王室危机前已经深入地方。莱恩哈特档案中的尤立卡回顾记载，发迹于采矿的新贵族通过许可外开采、囚犯劳动与人质控制维系矿石来源，地方执行官又能直接决定家属进入围栏和矿井。这些事实不等于全国每个领地都采用同样制度，却说明王国的统治并非只有君王个人发号施令。掌握产业、地方官员和武装的贵族已有独立行动能力，王室失势以后各方能够迅速扩张，正有此前长期积累的条件。","people":["推进之王","莱恩哈特"],"refs":[{"label":"《淬火尘霾》11-16 · 行动后〈荣光猎场〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_main_11-14_end.txt","evidence":"game"},{"label":"莱恩哈特·档案资料三","url":"https://prts.wiki/w/%E8%8E%B1%E6%81%A9%E5%93%88%E7%89%B9#档案资料","evidence":"game","note":"依据本地官方handbook对应条目核对，链接为游戏档案展示页。对幕后有意安排的猜测不采为已证实事实，仅取已叙述的劳动与管制制度。"}]}]},"kazdel":{"id":"kazdel","intro":"卡兹戴尔的起源早于如今的城市，也早于萨卡兹这一称谓。最初的提卡兹与源石接触、王冠的出现、失去家园及各支王庭迁徙，先后改变了族群的形态和共同体结构，898年的重建只是漫长历史中的一次重新开始。","scope":"从提卡兹最早的源石接触和魔王记忆，写至失乡、王庭分化与近代毁城战争以前的长期迁徙；后接898年双子戴冠及移动城重建。","chronologyNote":"提卡兹时代没有可在此换算的公历建国年。独眼巨人北迁明确早于泰拉纪年开端，其余王庭分离未能排出完整先后；阶段按可确证的共同体变化组织，未以传说中的毁城次数代替完整年表。","periods":[{"id":"kazdel-first-king","period":"提卡兹早期，泰拉纪年以前","title":"最初魔王与源石带来的转变","body":"萨卡兹的早期族群曾被称为提卡兹。主线中的变形者记忆表明，在能够说话、确认自我以前，它们已经存在许久；最初的提卡兹魔王接触源石之后，第一个个体从集群中站起，诸个体开始感知彼此并进行思考。凯尔希指出，受到改变的不只是变形者，早期血魔、女妖、温迪戈等同样在源石影响下发生转变，逐步接近另一种曾存在的生物形态。\n\n这段记忆把源石、族群形态和智慧的形成联系起来，却没有给出第一位魔王的个人姓名与建国年份。特雷西斯后来在信息流中见到的古老影像，则显示一名头戴黑冠的提卡兹走出银色山脉、仰望星空。它能与魔王和王冠的源头相互参照，但不能据这一短暂画面补全加冕仪式、疆界和行政制度。此时的卡兹戴尔，应先从早期族群共同体来理解，而不是把现代移动城的组织形式倒推到起点。","people":["凯尔希","特雷西斯"],"refs":[{"label":"《慈悲灯塔》14-8 · 行动后〈抵近支援作战〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_main_14-07_end.txt","evidence":"game"},{"label":"《离解复合》15-2 · 行动后〈执此剑者〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_main_15-01_end.txt","evidence":"game","note":"仅取古代信息影像，不把特雷西斯观看影像的年代视作影像发生年。"}]},{"id":"kazdel-loss-of-home","period":"提卡兹失去旧日家园的漫长时期","title":"外来战争与萨卡兹称谓形成","body":"在血魔大君的古老记忆里，卡兹戴尔曾不是一座都城或一个边界分明的国家，而是提卡兹能够看到的整个世界。后来外来族群的扩张与战争使他们失去家园，原有的共同空间不断被压缩。凯尔希概括，这些失去故乡的提卡兹成为被称为无根之人的萨卡兹；称谓的变化因此同时涉及土地丧失与社会身份，不能只按外貌把它理解成一次简单的改名。\n\n失乡以后，萨卡兹多次尝试重建卡兹戴尔，又在战争中再次失去它。不同年代的人说起这个名字时，所指可能是旧有土地、正在营建的聚落，也可能是流亡者希望回归的家园。血魔坚持卡兹戴尔本应覆盖整片大地，是他在当代冲突中的政治主张，不宜据此画出一张经过核实的古帝国疆域图。能够确认的是，家园被夺与长期迁徙成为共同记忆，也使其后许多萨卡兹在外地被当作雇佣兵和战争工具。","people":["凯尔希"],"refs":[{"label":"《淬火尘霾》11-17 · 行动前〈回答我〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_main_11-15_beg.txt","evidence":"game"},{"label":"《怒号光明》M8-2 · 幕间〈失语，产自多言〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_st_08-02.txt","evidence":"game"},{"label":"《遗尘漫步》WD-7 · 行动后〈家园〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act18d0/level_act18d0_07_end.txt","evidence":"game"}]},{"id":"kazdel-court-dispersal","period":"泰拉纪年以前开始，历经千年","title":"独眼巨人北迁与王庭分化","body":"独眼巨人的迁徙有一条明确早于纪年开端的线索。逻各斯整理凛视相关资料时指出，这不是一次被完整记录的大规模出走，而是成员在千年间逐一迁往北方，逐渐退出其他萨卡兹的视野。王庭始终知道他们的去向，也知道新的卡兹戴尔不会为他们而建；他们的关注已经转向无尽冰原，而非共同体本身的命运。\n\n同一档案还将北迁起点与一位独眼巨人魔王的时代相联系。某些古籍解释迁徙为对同族的失望，又说这位能够预见命运的君主接受了刺杀；对于这些原因，逻各斯保留了文献互异和推测性质。能确定的是，魔王传统没有保证所有王庭永远生活在同一城市。北迁、东行以及散居他国，使宗主称号、文化归属与现实居住地逐渐分离。后来的十王庭因此既是一种历史共同体，也包含已经长久离开核心地区的分支，而非十支始终齐整的中央部队。","people":["凛视","逻各斯"],"refs":[{"label":"凛视·档案资料四","url":"https://prts.wiki/w/%E5%87%9B%E8%A7%86#档案资料","evidence":"game","note":"依据本地官方handbook对应条目核对，链接为游戏档案展示页。"},{"label":"《破碎日冕》10-1 · 幕间〈被追逐者〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_st_10-01.txt","evidence":"game","note":"十王庭王帐多已空置，是对长期分散状态的回顾。"}]},{"id":"kazdel-before-898","period":"898年毁城战争以前及该次战争背景","title":"旧城反复毁建与王庭战争结构","body":"在双子成为后来重建的主导者以前，卡兹戴尔已经多次被建立又摧毁。流散各地的萨卡兹并未共同享有稳定生活，历代魔王与王庭的存在，也没有让城市免于再受战争。特雷西斯后来回顾，两百年前那场战争即使打退外敌，也未能保住城市；原有政治结构与军事力量并没有足够能力同时保全战场和居民的家园。\n\n当时的敌人包括来自核心圈的军队，特雷西斯记得高卢炮兵围城，也记得维多利亚蒸汽骑士踏上卡兹戴尔。战争造成的创伤不仅表现为城墙毁坏，还导致王庭人员死亡、居民流散，幸存各支随后作出不同选择。这里止于旧城市毁灭与重新集结的必要性：以勒什的死亡、熔炉爆炸、特蕾西娅和特雷西斯找到王冠，以及移动城市的营建，将在后篇898年的阶段继续。毁灭与重建之间的长期落差，是理解双子后来为何重组军政和寻求另一种生活的起点。","people":["特蕾西娅","特雷西斯"],"refs":[{"label":"《破碎日冕》10-1 · 幕间〈被追逐者〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_st_10-01.txt","evidence":"game"},{"label":"《淬火尘霾》11-14 · 行动前〈一场相见〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_main_11-12_beg.txt","evidence":"game"},{"label":"《淬火尘霾》11-4 · 幕间〈何谓理想〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/obt/main/level_st_11-01.txt","evidence":"game"},{"label":"逻各斯·档案资料二","url":"https://prts.wiki/w/%E9%80%BB%E5%90%84%E6%96%AF#档案资料","evidence":"game","note":"依据本地官方handbook对应条目核对，链接为游戏档案展示页。仅取古代战争造成王庭创伤的回顾，不前移女妖后来迁居的结果。"}]}]},"rim":{"id":"rim","intro":"雷姆必拓的国名、矿业组织与各自治州不能简单合成一家公司的创办史。现有直接资料能够追溯总工会许可、外来采矿资本、矿镇扩张和围栏抗争，却不足以确认全国最初建国的精确年份。","scope":"以莱恩哈特本体档案为据，从早期矿业许可写至跨境资本、许可外开采和围栏抗争爆发前的制度条件；事件本体仍见后篇围栏阶段。","chronologyNote":"国家最初建制及早期矿业制度的精确年份未明，本篇止于围栏事件爆发前的条件。围栏结束早于暴行与博士、阿米娅同行，但与舰船出土及幼年救援尚不能完全互定年；后篇两线应分别保留。","periods":[{"id":"rim-early-mining-permits","period":"淘矿热兴起以前，具体年份未明","title":"矿镇开发与总工会许可制度","body":"本篇能够直接核实的早期雷姆必拓，已经拥有矿镇、矿队和总工会，不是一片等待外来者首次发现的无人土地。莱恩哈特档案所录矿镇居民的回顾称，维多利亚经营蒸汽技术的商人来到当地，与总工会签下有限许可，缴税后运走矿石，再回国建立工厂。采矿范围受到约定，外来经营者需要与当地既有组织交涉，这是后来冲突中判断许可内外的重要前提。\n\n这份材料没有交代总工会成立于何年，也没有列出全国统一建国的仪式。它能确认的是，在淘矿热和大规模外资扩张以前，当地已有组织资源开采和收税的制度，矿业并非完全由维多利亚创建。矿镇居民、采矿劳动者、运输商人与工会各有自己的位置；这些关系随后被资本扩张改变，却不能因此把最初的当地社会从历史中抹去。","people":["莱恩哈特"],"refs":[{"label":"莱恩哈特·档案资料二","url":"https://prts.wiki/w/%E8%8E%B1%E6%81%A9%E5%93%88%E7%89%B9#档案资料","evidence":"game","note":"依据本地官方handbook对应条目核对，链接为游戏档案展示页。早期回顾来自档案所录酒馆交谈，人物未提供精确年份。"}]},{"id":"rim-mining-capital-growth","period":"淘矿热与跨境商道发展时期","title":"矿石贸易扩大与新贵族形成","body":"取得许可的商人把雷姆必拓的矿石投入蒸汽工业，工厂壮大以后，部分人在维多利亚成为权贵，产业也继续扩张。他们在两地商道之间建起小型移动城市，使矿镇、加工厂与运输路线的联系更加紧密。贸易给当地带来外来商品和经营机会，也让远方工厂对矿石的需求越来越深地作用于矿区。\n\n档案中的讲述者记得，淘矿热期间商队频繁往返，后来商队减少，商道上却出现虚弱的老人、妇女和孩子。这些人的处境提醒当地居民，跨越辖外荒野并不是一段可以徒步轻易完成的路程，连受过训练的信使都需要载具和足够补给。商业城市与矿业资源的增多，没有自动给所有参与者带来同等的安全。工厂、新贵族和小型移动城是这一阶段明确的变化，不能由此推定总工会已经控制每家公司，或把所有自治州当成同一企业的下属矿场。","people":["莱恩哈特"],"refs":[{"label":"莱恩哈特·档案资料二","url":"https://prts.wiki/w/%E8%8E%B1%E6%81%A9%E5%93%88%E7%89%B9#档案资料","evidence":"game","note":"依据本地官方handbook对应条目核对，链接为游戏档案展示页。"}]},{"id":"rim-coercive-extraction","period":"围栏事件爆发以前","title":"许可外开采与囚犯家属劳役","body":"矿石需求扩大以后，部分维多利亚新贵族不再满足于原有许可。他们把被剥夺公民权的囚犯送入雷姆必拓，充当夺取许可外矿石的矿匪；总工会因种种限制没有公开解决，问题因此持续。囚犯并非全是无差别的罪犯，档案中的前书记员自述曾因参加联名抗议受到陷害，入狱后才被迫成为矿匪，说明这种制度也能被用来排除异议者。\n\n控制又延伸到家属。执行官将老弱妇孺圈入简陋围栏，强迫他们下井参与开采和精炼，以家属处境维系整个劳动体系。人质消息外泄、守备松弛与武器失修，为后来的抗争提供条件。受访者怀疑这一连串异常可能受幕后交易推动，但那只是他的判断；能够确认的是，恶劣劳役曝光引起众怒，雷姆必拓工人开始帮助被控制的人，并不是单靠贵族内部谈判解决了问题。","people":["莱恩哈特"],"refs":[{"label":"莱恩哈特·档案资料二","url":"https://prts.wiki/w/%E8%8E%B1%E6%81%A9%E5%93%88%E7%89%B9#档案资料","evidence":"game","note":"依据本地官方handbook对应条目核对，链接为游戏档案展示页。"},{"label":"莱恩哈特·档案资料三","url":"https://prts.wiki/w/%E8%8E%B1%E6%81%A9%E5%93%88%E7%89%B9#档案资料","evidence":"game","note":"依据本地官方handbook对应条目核对，链接为游戏档案展示页。保留前书记员的经历与制度事实，不把其幕后交易推断写成定论。"}]}],"supplementalPeriods":[{"targetStoryId":"rim-departure","targetPhaseIndex":1,"id":"rim-stockade-and-autonomy","period":"围栏事件及其后，早于暴行与博士同行","title":"围栏解放与尤立卡自治变化","body":"围栏中的家属处境推动工人参与解放行动，莱恩哈特也深入围栏，因实际帮助被一部分见证者称为英雄。原有执行官在斗争中失去对当地的控制，但并非全部死亡，一些残余仍可能在荒野袭击单独活动的信使。档案所录官邸谈话显示，尤立卡自治州已经能够与罗德岛洽谈办事处和人才引荐，而受访者认为其行政归属可能进一步转向雷姆必拓；后一项在当时仍是预测，不宜直接写成已经完成的全国独立。\n\n暴行从亲历者角度补充了另一面：商人以共同开发为名签约，转头却围起土地，把当地人排除在外；一些原本与她共同反抗的人取得名望后，也开始像商人与矿匪一样对待他人。这使她在事件结束后选择离开原有环境，转而与博士和阿米娅旅行。围栏抗争带来实际解放和地方权力变化，却没有令矿业中的压迫、安全差异与感染者处境一次解决，后篇矿井与运载车故事正发生在这些问题仍持续的雷姆必拓。","people":["莱恩哈特","暴行","博士","阿米娅"],"refs":[{"label":"莱恩哈特·档案资料三","url":"https://prts.wiki/w/%E8%8E%B1%E6%81%A9%E5%93%88%E7%89%B9#档案资料","evidence":"game","note":"依据本地官方handbook对应条目核对，链接为游戏档案展示页。"},{"label":"《去咧嘴谷》幕间〈落定的锤子〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act16mini/level_act16mini_st04.txt","evidence":"game"}]}]},"bolivar":{"id":"bolivar","intro":"玻利瓦尔的国家形态形成于多次外部统治与反抗。伊比利亚的矿产开发、莱塔尼亚扶持的王朝、哥伦比亚支持的政府以及本土反抗军先后进入这片土地，最后留下三方战争中的分裂国家。","scope":"从殖民以前的地名与伊比利亚附属地，写至辛嘉斯王朝、联合政府及真正玻利瓦尔人的形成；止于多索雷斯大奖赛篇章之前的格局。","chronologyNote":"早期顺序主要依据《多索雷斯假日》DH-ST-3中埃内斯托向陈所作的历史追述；“一百三十年”和“两百年前”保留原有相对表达，不推算未经直接确认的建国年。其对城市繁荣的政治评价与可确认事件分别处理。","periods":[{"id":"bolivar-iberian-dependency","period":"伊比利亚统治以前及附属地时期，确切年份未明","title":"玻利瓦尔平原与伊比利亚开发","body":"玻利瓦尔最早作为一片平原的名称出现在已公开的历史追述中。埃内斯托向陈说明，伊比利亚人到来时发现了大量源石矿脉，继而留驻并将这片土地变为附属地。现有这段史述没有说明此前各原住民社会的政治组织，也未给出一位可以确认为全国建国者的人物。因此，地名的出现、原住民长期生活与后来殖民政权的建立，需要分开理解。\n\n开发使土地和资源进入外部国家控制的网络。后续剧情提到的伊比利亚—萨尔贡—玻利瓦尔商道，又显示这片地区的物产参与了跨地域贸易：萨尔贡的统治者同意商道开拓后，引入玻利瓦尔的甘蔗与咖啡豆。矿脉与作物的流通共同构成了这段前史的经济背景。伊比利亚统治后来终结，但DH-ST-3并未详述其结束的直接原因，本篇不以别处灾难的日期替代这一缺失。","people":[],"refs":[{"label":"《多索雷斯假日》DH-ST-3 · 幕间〈请君入瓮〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act12side/level_act12side_st03.txt","evidence":"game"},{"label":"《太阳甩在身后》AS-8 · 行动前〈黄沙尽头〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act35side/level_act35side_08_beg.txt","evidence":"game"}]},{"id":"bolivar-singas-dynasty","period":"伊比利亚退出后；距DH篇章约两百年前","title":"长期动荡与辛嘉斯王朝形成","body":"伊比利亚统治结束以后，玻利瓦尔经历了一百三十年的混乱，随后莱塔尼亚势力进入。这次更替没有立即带来独立，玻利瓦尔先成为莱塔尼亚的附属地，后来才从附属地转为附属国，形成辛嘉斯王朝。埃内斯托把这一转变放在约两百年前，并认为现在的玻利瓦尔由此开始形成；这是一段明确的建制演变，而不是单纯更换驻军。\n\n王朝的形成也未消除本土社会与统治阶层之间的距离。按照埃内斯托的叙述，辛嘉斯王朝的人并不认同玻利瓦尔人的称谓。后来人物经历中反复出现王朝种植园及从中逃离的劳动者，说明王朝的存在同时落实为对土地、生产与人口的控制。公开剧情能够支持附属地、附属国、王朝这条先后链条，却没有在这些段落中完整列出历代君主、建都过程和疆域变迁；本篇不另补一套王朝世系。","people":[],"refs":[{"label":"《多索雷斯假日》DH-ST-3 · 幕间〈请君入瓮〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act12side/level_act12side_st03.txt","evidence":"game"},{"label":"《水晶箭行动》CR-1 · 行动前〈城市主题展〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act32side/level_act32side_01_beg.txt","evidence":"game","note":"后出的对话回顾来自辛嘉斯种植园的逃亡者，不据此替王朝建立定年。"}]},{"id":"bolivar-columbian-intervention","period":"莱塔尼亚巫王时期","title":"哥伦比亚入侵与联合政府建立","body":"巫王统治时期，莱塔尼亚试图以玻利瓦尔为支点，在哥伦比亚制造内乱。计划没有成功，反而引来哥伦比亚入侵玻利瓦尔，联合政府在这一过程中成立。玻利瓦尔由此出现了分别依赖莱塔尼亚与哥伦比亚的权力中心，外部竞争不再只是外国之间的边境纠纷，而成为本地两套统治机构互相对抗的条件。\n\n埃内斯托对两国态度的概括是：莱塔尼亚投入有限，哥伦比亚虽谋求更多利益，却无法一次吞并整个地区，双方因而陷入拉锯。这里可以确认的结果，是辛嘉斯王朝和联合政府同时存在，战争没有以一方完成统一告终。玻利瓦尔人由此面对彼此冲突的军事与政治旗帜。同样以国家为名行动的组织，并不遵循同一指挥链，也不承担同一政治目标；不能把其中任何一方的机构，直接当作全国已经统一的军政体系。","people":[],"refs":[{"label":"《多索雷斯假日》DH-ST-3 · 幕间〈请君入瓮〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act12side/level_act12side_st03.txt","evidence":"game"}]},{"id":"bolivar-three-sided-war","period":"两大阵营对峙后至多索雷斯大奖赛以前","title":"本土反抗军兴起与三方战争","body":"不能忍受长期外部控制与战争的玻利瓦尔人组织起反抗军，自称真正玻利瓦尔人，希望建立独立国家。反抗没有终结既有战事，反而使王朝、联合政府与反抗军形成三方对峙。三个阵营各自声称代表国家，却都无法结束其他力量的存在，居民面对的仍是征召、战场、破坏和不断变动的控制范围。\n\n潘乔曾经相信，只要赶走联合政府和辛嘉斯王朝，和平就会到来；多年的作战却使他看到真正玻利瓦尔人的队伍也可能陷入只为继续战争而行动的状态。这是他在参赛危机前已经积累的政治失望，不能据此简单等同所有本土反抗者的动机。与此同时，多索雷斯在坎黛拉经营下逐步成为能与三方交涉、吸引资本和游客的城市。它没有统一全国，而是在战争格局中取得特殊位置；这正是后篇城市经营与潘乔家庭故事开始时已存在的条件。","people":["潘乔","坎黛拉","龙舌兰","羽毛笔"],"refs":[{"label":"《多索雷斯假日》DH-ST-3 · 幕间〈请君入瓮〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act12side/level_act12side_st03.txt","evidence":"game"},{"label":"《多索雷斯假日》DH-7 · 行动前〈沙滩阻击〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act12side/level_act12side_07_beg.txt","evidence":"game"}]}]},"higashi":{"id":"higashi","intro":"东国早期完整建国年表尚不能由本篇直接核实，但游戏保留了族群东迁、武家衰亡、南北政权立法与南院近代转型的具体记忆。这些前史解释了神社、家族、地方武装和工业城市为何同时存在。","scope":"以星熊本体及异格档案、《墟》对早年的追述为主，串联鬼族迁徙传统、武家与姓氏制度、血峰战役后地方秩序和近代工业化，不重复后篇人物出走与露华村行动。","chronologyNote":"奎隆东迁与死亡有互相矛盾的传说，鬼菖蒲败亡未在所核条目中给出确年。1073年地方冲突出自游戏内百科摘录，保留其材料性质。南院议会、工业化与人物早年有时间交叠，按明确的制度转变叙述，不虚构统一建国日。","periods":[{"id":"higashi-eastern-migration","period":"远古东迁传统，具体年代未明","title":"奎隆东行与鬼族来源的记忆","body":"东国鬼族的来源与萨卡兹东迁存在关联。星熊在谈论自身家世时，承认奎隆东行把阿纳萨和鬼带到炎国与东国，却拒绝因此认定自己是奎隆的后裔。族群迁徙与个体血统并不是同一个结论，她的态度为这段前史划出了清楚的边界：早期族群变化可以成为共同记忆，却不足以给现代每个人建立一套王族家谱。\n\n关于东迁首领最终的命运，东国仍流传不同故事。三船讲述过奎隆试图保护被迫成为苇原之民的鬼族、却在失控中连同要保护的人一起杀死的版本，并明言铁斋至少讲过三种互相矛盾的死法。这些材料反映了鬼族曾经历迁徙、分离和被纳入其他秩序的历史记忆，但不能据此确认某场屠杀的全部过程，更不能把轮回、涅槃等叙述补成已证实的建国事件。东国最早国家的具体建立者与确年，仍需更多直接史料。","people":["星熊"],"refs":[{"label":"斩业星熊·晋升记录","url":"https://prts.wiki/w/%E6%96%A9%E4%B8%9A%E6%98%9F%E7%86%8A#档案资料","evidence":"game","note":"依据本地官方handbook对应条目核对，链接为游戏档案展示页。"},{"label":"《墟》AT-5 · 行动后〈遗祸〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act44side/level_act44side_05_end.txt","evidence":"game"}]},{"id":"higashi-warrior-name-laws","period":"鬼菖蒲征作死后至南北政权立法时期","title":"武家败亡与鬼族姓氏法令","body":"星熊说明，鬼族只称名字、不称姓氏的习俗，与鬼菖蒲征作死后的避祸有关。部分后人投奔僧院，隐去本名、只用法号，也有人出于崇拜而冒称其后裔。时间推移以后，真正的血缘继承、政治认同和保护自身的改名行为逐渐混杂，名字本身已不能可靠地证明家世。武家历史因此并非只保存在家谱中，也进入普通人的称呼和宗教生活。\n\n这种习惯给课税与战场指挥造成实际困难。北院后来颁布要求万民使用姓氏的法令，南院也制定类似规则，以尊重东皇赐姓传统为由，要求主要受到影响的鬼族恢复姓氏。两边又禁止无姓者自行恢复鬼菖蒲姓，引发不配合，执行最终不了了之。这段回顾直接表明，南北政权都试图通过姓名登记把人口纳入行政管理，却都遭遇了历史身份与实际服从之间的阻力；它不是一项仅凭颁布便完成的全国统一改革。","people":["星熊"],"refs":[{"label":"斩业星熊·晋升记录","url":"https://prts.wiki/w/%E6%96%A9%E4%B8%9A%E6%98%9F%E7%86%8A#档案资料","evidence":"game","note":"依据本地官方handbook对应条目核对，链接为游戏档案展示页。铁斋对星熊家具体姓氏的说法被本人质疑，本篇不据此认定其祖系。"}]},{"id":"higashi-postwar-local-order","period":"血峰战役后，1073年及其后数年","title":"战后溃兵与地方武装秩序","body":"血峰战役的结束没有立即给东国各地带来安定。星熊档案收录的一段游戏内百科资料记载，1073年，一批持续游荡于南院的溃兵袭击控制锻冶町的金石会。金石会虽然获胜，第一代会长却战死，铁斋的直系亲属也全部遇害。随后铁斋接任会长，以残酷手段追杀涉事人员，冲突扩展为御机长期、大规模的暴力对抗。材料同时保留了复仇与借机扩张两种解释，本篇不替它消除分歧。\n\n这段地方历史呈现了国家战争与街区武装之间的连续影响：战场遗留的人员和武器没有随停战消失，帮派又承担治安、产业和人身依附的一部分职能。星熊回忆父亲去世时，御机仍未完全摆脱战后混乱，街区与家族因而承受着超出单场战争的损失。后来的工业繁荣是在这样的地方权力网络中形成的，不是先有一个彻底和平、秩序统一的社会，然后才突然出现黑道。","people":["星熊"],"refs":[{"label":"斩业星熊·档案资料三","url":"https://prts.wiki/w/%E6%96%A9%E4%B8%9A%E6%98%9F%E7%86%8A#档案资料","evidence":"game","note":"依据本地官方handbook对应条目核对，链接为游戏档案展示页。原条目明确为游戏内爱好者百科摘录，发生年照录其陈述，动机争议不裁定。"},{"label":"《墟》AT-2 · 行动前〈灵异特辑〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act44side/level_act44side_02_beg.txt","evidence":"game"}]},{"id":"higashi-industry-representation","period":"战后复苏与南院首届议会选举前后","title":"晶体产业发展与南院政治转型","body":"战后晶体产业逐步发展，旧有武家与地方组织开始进入新的生产关系。三船回忆，铁斋曾从光元一系衰落公家取得铸盾工艺；与此同时，南院第一届议会准备选举，议员将从平民中选出的消息震动社会。旧身份并未因此消失，工厂、家族名义、地方武装与新的政治职位反而在转型中互相联系。普通人可以被纳入新的代表制度，但地方强者也会争取这种合法位置。\n\n《墟》的历史回顾进一步指出，血峰战役以后南北冲突并未停止，只是经济高速发展使城市居民越来越少关注边境。南院的御机与北方的锁川维持不同权力中心，工商发展和跨境联系又让双方并非全无往来。后来的遥档案中，一名东国要人的自述还说明财富能够改变大家族的实际掌权者，家名不再总与原来的血统重合。这是近代政经结构变化的旁证，不能据此断言所有传统阶层已经退出；后篇人物所处的，正是这些制度并存的东国。","people":["星熊","遥"],"refs":[{"label":"《墟》AT-4 · 行动前〈百物语〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act44side/level_act44side_04_beg.txt","evidence":"game"},{"label":"《墟》AT-7 · 行动前〈冷月〉","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act44side/level_act44side_07_beg.txt","evidence":"game"},{"label":"遥·晋升记录","url":"https://prts.wiki/w/%E9%81%A5#档案资料","evidence":"game","note":"依据本地官方handbook对应条目核对，链接为游戏档案展示页。要人的话是对现实利益的自我陈述，其合理化污染和牺牲居民的立场不作为本文结论。"}]}]},"kjerag":{"id":"kjerag","intro":"谢拉格的政治共同体早于喀兰贸易。它先以耶拉冈德及共同信仰凝聚，后来形成圣女、蔓珠院与三大家族相互制约的秩序；近代工业化首先改变的，正是这套长期沿用的治理结构。","scope":"从建国经文及圣女制度的旧史，写至恩希欧迪斯与诺希斯在海外重订改革目标；后接《风雪过境》的开放与三族冲突。","chronologyNote":"建国与早期制度没有可确认的公历年份。经文中的三百年、百次献祭和千年前是不同叙述层次，不能直接相加换算建国年。早期宗教史保留经文与后世口述之间的差异；列车事故依据菈塔托丝事后的具体说明。","periods":[{"id":"kjerag-foundation-tradition","period":"年代不详，三族分治以前","title":"耶拉冈德的聚众与王国建立","body":"谢拉格的建国记述保存在《耶拉冈德》中。经文说，这片山地起初只有分散生活的人，耶拉冈德化作人形，与他们共同生存；人们畏惧祂的力量，也在祂身边逐渐聚集，最终形成名为谢拉格的国家，并奉祂为第一代国王。后来的谢拉格人仍以祂为土地的命名者，把共同的语言、生活与信仰作为国民身份的依据。\n\n同一部经典又记载，祂执掌王国三百年后，将王位交给副手，消失在风雪之中。这里能确认的是谢拉格人所承认的国家起源及神权退居幕后的传统，不能由此确定真实的建国日期，也不能把后来的三位家主直接写成祂当时指定的全部继承人。","people":["耶拉"],"refs":[{"label":"风雪过境·BI-1 · 行动后 不欢而聚","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act14side/level_act14side_01_end.txt","evidence":"game"},{"label":"风雪过境·BI-ST-4 · 幕间 封盘","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act14side/level_act14side_st04.txt","evidence":"game"}]},{"id":"kjerag-first-saint","period":"约千年前的旧史，具体年月不明","title":"献祭传统与首任圣女诞生","body":"蔓珠院流传的正式说法是：祖先触怒神明，严冬来临，院中每年选出少女登山献祭，直到第一百位少女唤回耶拉冈德，才结束严冬，并成为第一任圣女。圣女的宗教权威、银铃以及登山仪式，因而被解释为神明回应人的凭据。\n\n雅儿曾提示典籍另存不同版本。恩雅后来谈起一段未列入正史的传闻：长期没有神迹引发民众围攻蔓珠院，部分修士携经书躲入山中避难所，许多经典因此出现断代，直到少女唤醒神明，动乱才平息。两种叙述都解释了圣女制度的形成，却对人们为何登山、蔓珠院经历了什么有不同记忆；前史保留这一差别，不将献祭传说直接当作逐年可核的编年记录。","people":["耶拉","初雪"],"refs":[{"label":"风雪过境·BI-5 · 行动前 猎场","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act14side/level_act14side_05_beg.txt","evidence":"game"},{"label":"雪山降临1101·OS-7 · 行动后 焚心灼影","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act46side/level_act46side_07_end.txt","evidence":"game"}]},{"id":"kjerag-three-clans","period":"延续数百年的三族分治时期","title":"三族领地与蔓珠院秩序","body":"在神明不再亲自理政之后，希瓦艾什、布朗陶、佩尔罗契三族分别管理领地，蔓珠院维系共同宗教，三族议会处理各家事务与大典安排。这套制度维持了数百年，也让领民对家族的归属逐渐强于对整个谢拉格的共同认识。菈塔托丝回顾旧制时指出，人们生活相近，却因所属家族不同而越发疏远。\n\n封闭环境使这种分治长期不必接受外部竞争的检验。三族可以各自保持秩序，议会却逐渐只剩惯常事务与节庆分摊。近代改革面对的并不是一张空白的行政地图，而是已有土地、信仰、家族责任与利益分配相互联系的国家。","people":["菈塔托丝","初雪","银灰"],"refs":[{"label":"风雪过境·BI-6 · 行动后 歧路","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act14side/level_act14side_06_end.txt","evidence":"game"},{"label":"风雪过境·BI-1 · 行动后 不欢而聚","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act14side/level_act14side_01_end.txt","evidence":"game"}]},{"id":"kjerag-industrial-parents","period":"恩希欧迪斯少年时期","title":"工业化尝试与列车事故后果","body":"恩希欧迪斯父母推动工业化时，遭到老卢卡及佩尔罗契前任家主反对。后来二人死于列车事故，调查责任被推给埃德怀斯一家，诺希斯随父母离开谢拉格。菈塔托丝在多年后说明，老卢卡确实准备过机关房暗杀，并得到另一位家主默许，但夫妇在赴约途中已遇事故，计划没有实施；老卢卡利用事故栽赃，才是实际发生的政治行动。\n\n事故摧毁了改革者之间原有的家庭联系，也使孩子们背负互相猜疑。恩希欧迪斯没有认定童年的诺希斯是凶手，两人仍记得共同建设强国的愿望。临别时，诺希斯决定赴维多利亚学习先进知识，恩希欧迪斯也提出以后外出求学再回来的打算。","people":["银灰","灵知","菈塔托丝"],"refs":[{"label":"风雪过境·BI-6 · 行动后 歧路","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act14side/level_act14side_06_end.txt","evidence":"game"},{"label":"风雪过境·BI-6 · 行动前 歧路","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act14side/level_act14side_06_beg.txt","evidence":"game"}]},{"id":"kjerag-overseas-reformers","period":"海外求学时期，返回谢拉格之前","title":"海外见闻与共同改革目标","body":"青年恩希欧迪斯在维多利亚学会与贵族交涉，诺希斯则研究生命科学与源石解析。再次相会时，他们已经用不同方式进入外部世界。恩希欧迪斯从哥伦比亚崛起、高卢覆灭及国家交往的加密中判断，谢拉格无法永远依赖封闭获得安全，必须趁仍有主动权时与外界接触。\n\n他邀请诺希斯帮助自己，把童年的强国愿望转成引进知识、技术和资源的具体方向。两人的合作因此早于后来的雪山事变；它既承接父辈未完成的建设，也带着对谢拉格处境的新判断。随后建立喀兰贸易、回国推动开放以及与三族旧制的正面冲突，进入现有地区纪事。","people":["银灰","灵知"],"refs":[{"label":"风雪过境·BI-6 · 行动前 歧路","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act14side/level_act14side_06_beg.txt","evidence":"game"}]}]},"yan":{"id":"yan","intro":"炎国的前史包含两条彼此相连的进程：人群在真龙统治下形成国家，以及国家逐步摆脱巨兽支配、建立城市与知识制度。千年前的大狩猎是重要转折，却不是全部历史的起点。","scope":"从百氏之乱与早期国家形成，写至大狩猎、建都旧史、司岁台制度和长期边防农业建设；止于当代玉门危机与尚蜀岁相事件之前。","chronologyNote":"游戏确认百氏之乱、千年前大狩猎及战后岁片段的相对关系，未完整公开开国君主谱系和建国年份。百灶建城记述只称在一场大战后，不能擅自确定就是大狩猎，故与千年前变局并列说明。百年前变故与近现代建设采用相对年代，不换算未经明确记载的公历年份。","periods":[{"id":"yan-early-unification","period":"国家形成的早期，具体年代不详","title":"百氏之乱与真龙统治确立","body":"炎国的统一不是从当代朝廷或岁片段的活动开始。《怀黍离》中，绩与左乐谈到最初的百氏之乱，明确把真龙结束纷争与岁兽的介入联系起来。岁曾利用自身力量帮助真龙赢得征伐，这使国家形成史与巨兽活动从一开始便相互交织。左乐承认这段历史，却拒绝将其解释为人必须永远报答的神恩。\n\n这段可考旧史说明，早期的权力整合曾借助超越人类的力量；也说明后来炎国与岁的战争，并非从未合作过的双方突然敌对。现有对话没有给出各氏族的完整名单、统一战争的起讫年或连续的君主年表，不能据此补造朝代更替。后世所谓真龙的血统和君位，是这段早期建制长期延续下来的政治背景。","people":["望","绩","左乐"],"refs":[{"label":"怀黍离·HS-5 · 行动前 纺绫罗","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act31side/level_act31side_05_beg.txt","evidence":"game"},{"label":"登临意·WB-9 · 行动后 “冬藏”","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act23side/level_act23side_09_end.txt","evidence":"game"}]},{"id":"yan-hunt-and-capital","period":"千年前的大狩猎；建都旧事的具体先后未明","title":"大狩猎转折与百灶建城旧史","body":"千年前，炎国与巨兽展开被后人称为大狩猎的战争。梁洵解释，当时的人是在向无法匹敌的神明争取生存空间；睚则从巨兽一方记得岁协助人类驱逐、围杀同类。两种叙述立场不同，却都确认人、国家与巨兽的关系发生了根本变化。后来，方士找到特殊源石并将其献给真龙，成为结束狩猎的关键武器；启用其全部力量必须付出在位真龙性命的约束，则延续为“不反”制度。\n\n百灶的建都记述也与古代战后建设有关，但文本未明确指出是哪一场大战。战场附近发现富饶矿脉，却因源石富集而危及周边土地。天师提出在矿脉上建设城市，利用高耗能设施持续消耗能量。真龙采纳建议，先遣能人进入灾域，五十三年后城成定都，取照拂天下烟火之意命名百灶。它既是政治中心，也是长期利用和约束源石力量的工程。","people":["重岳","梁洵","莫佚"],"refs":[{"label":"相见欢·OR-2 · 行动前 糖瓜粘","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act40side/level_act40side_02_beg.txt","evidence":"game"},{"label":"登临意·WB-9 · 行动后 “冬藏”","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act23side/level_act23side_09_end.txt","evidence":"game"},{"label":"辞岁行·TA-8 · 行动前 金错刀","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act49side/level_act49side_08_beg.txt","evidence":"game"},{"label":"相见欢·OR-2 · 行动后 糖瓜粘","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act40side/level_act40side_02_end.txt","evidence":"game"}]},{"id":"yan-sui-supervision","period":"大狩猎以后，延续至百年前的变故","title":"岁片段分化与司岁台监管","body":"岁陷入沉睡之后，其意识分裂出后来被称为代理人的多个个体。他们并非自始便有固定身份，而是在漫长混沌中逐渐意识到自身存在，又分别通过作画、下棋、种稼、铸造和诗歌等活动形成各自的生活。令对这一过程的回忆，将兄弟姐妹的长幼次序与各自最早回答“我是谁”的先后联系起来。\n\n炎国没有因为获得战时胜利便彻底摆脱岁的影响。司岁台成立并持续研究、记录和监管相关个体，到当代已有千年历史；国家安全与代理人的实际行动因此始终相连。百年前发生代理人死亡及望与朝廷决裂的变故。左乐在尚未掌握旧案全貌时，曾将其概括为罪人作乱导致代理人身死，并以此说明除岁的必要；这属于朝廷流传的旧案判断，并不能替代后来查明的实际经过。前史保留变故的时间位置，颉之死的责任与当代追索另在后续纪事展开。","people":["令","望","黍","左乐"],"refs":[{"label":"令·档案资料二","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/excel/handbook_info_table.json","evidence":"game","note":"干员档案数据：char_2023_ling，档案资料二"},{"label":"怀黍离·HS-5 · 行动前 纺绫罗","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act31side/level_act31side_05_beg.txt","evidence":"game"}]},{"id":"yan-frontier-and-agriculture","period":"长期边防与农业建设时期，当代危机以前","title":"玉门戍守与农业技术积累","body":"国家延续并不只依赖旧日武力。玉门保存着巨兽战争遗迹，后来又成为重岳长期任职的边塞。令曾由江南前往玉门，亲历把整座城当作诱饵、配合城外伏兵的苦战；重岳也曾因诏令往来北境战乱与江南匪患，最终把武术教习与戍守作为持续职责。这些经历发生在当代玉门守城之前，构成当地将士、朝廷与代理人之间长期合作的基础。\n\n另一边，农业研究从有限土地上的增产、防霜与抗旱，逐步发展到把田地搬上移动地块及探索无土栽培。黍作为农业天师参与这条延续千年的事业，依靠试验与积累解决现实种植问题，而非直接用权能替代所有劳作。到尚蜀、大荒城和玉门的当代事件开始时，炎国已经拥有边防城市、天师体系、农业基地与岁务监管机关；后续危机发生在这些既有制度之中。","people":["重岳","令","黍"],"refs":[{"label":"登临意·WB-9 · 行动后 “冬藏”","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act23side/level_act23side_09_end.txt","evidence":"game"},{"label":"重岳·档案资料四","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/excel/handbook_info_table.json","evidence":"game","note":"干员档案数据：char_2024_chyue，档案资料四"},{"label":"令·档案资料四","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/excel/handbook_info_table.json","evidence":"game","note":"干员档案数据：char_2023_ling，档案资料四"},{"label":"黍·档案资料三","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/excel/handbook_info_table.json","evidence":"game","note":"干员档案数据：char_2025_shu，档案资料三"}]}]},"siracusa":{"id":"siracusa","intro":"叙拉古并非一开始就由灰厅统治。它曾属于由金律乐章联系的莱塔尼亚，又经历脱离、家族争斗与西西里夫人的制度整合；现有故事里的新城改革，是对这些旧秩序的再次挑战。","scope":"从莱塔尼亚早期盟约中的叙拉古，写至独立、家族竞争、灰厅确立及三十年前的市政清洗；止于德克萨斯家族变故与当代沃尔西尼事件之前。","chronologyNote":"游戏将莱塔尼亚盟约置于一千多年前、叙拉古脱离置于一百多年前，将西西里夫人整合家族后的秩序描述为延续近六十年。这里不换算未经原文确认的建国年，也不将独立与灰厅建立写成同一事件。海外家族拓荒始于哥伦比亚初建，确切年份及其与灰厅形成的细部先后未给出。","periods":[{"id":"siracusa-old-alliance","period":"一千多年前的部族盟约时期","title":"莱塔尼亚盟约与地方家族传统","body":"叙拉古可考的早期政治关系，需要从莱塔尼亚的建立说起。一千多年前，不同部族的先贤在不死术师见证下缔结金律乐章，以共同旋律规定彼此关系，确立选帝侯制度，并形成共享的道德与审美。后来叙拉古的脱离之所以会动摇整个乐章，正因为它原本是这一共同秩序中的组成部分。\n\n部族盟约并没有消除各地原有生活和权力组织。西西里夫人谈起家族制度时，明确说它在自己出生以前就已存在千百年。家族因此既不是她为统一国家而凭空创设的机构，也不是新沃尔西尼时代才出现的黑帮称谓。后来所有改革，面对的都是早已积累了亲缘、忠诚、财富与武力关系的社会结构。最初定居与家族形成的详细年月，现有游戏原文尚未给出。","people":["西西里夫人","弗莱蒙特"],"refs":[{"label":"崔林特尔梅之金·ZT-4 · 行动后 狂想曲“望想” ","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act29side/level_act29side_04_end.txt","evidence":"game"},{"label":"崔林特尔梅之金·ZT-5 · 行动后 奏鸣曲“秋日” ","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act29side/level_act29side_05_end.txt","evidence":"game"},{"label":"叙拉古人·IS-10 · 行动后 “狼之主”","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act21side/level_act21side_10_end.txt","evidence":"game"}]},{"id":"siracusa-secession","period":"一百多年前起的独立纷争及近代拓荒","title":"叙拉古脱离与海外家族发展","body":"一百多年前，叙拉古人试图脱离莱塔尼亚，纷争持续数年。金律乐章失去一个声部，其他大区也随之陷入混乱。赫尔昏佐伦最终以个人力量挑战历代术师留在乐章中的力量，将叙拉古部分剔除，把剩余九个大区重新联系起来。叙拉古由此不再属于旧乐章维系的整体；这场脱离与后来西西里夫人建立灰厅，中间仍隔着其他历史变化。\n\n近代的新机会又把家族活动带向境外。哥伦比亚初建时，多个叙拉古家族派出队伍参与拓荒，在当地争取地盘和利益。萨尔瓦多雷·德克萨斯是其中成功者，逐渐建立自身家族，始终坚持叙拉古人的身份。海外发展没有自动解除原乡的身份和规则联系，反而让家族拥有两地资源，也为后来不同制度、技术与利益重新进入叙拉古留下了通道。","people":["巫王","德克萨斯","萨尔瓦多雷·德克萨斯"],"refs":[{"label":"崔林特尔梅之金·ZT-4 · 行动后 狂想曲“望想” ","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act29side/level_act29side_04_end.txt","evidence":"game"},{"label":"崔林特尔梅之金·ZT-4 · 行动前 狂想曲“望想” ","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act29side/level_act29side_04_beg.txt","evidence":"game"},{"label":"叙拉古人·IS-1 · 行动前 雨落无声","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act21side/level_act21side_01_beg.txt","evidence":"game"}]},{"id":"siracusa-grey-hall","period":"约六十年前起","title":"家族战争收束与灰厅制度建立","body":"在西西里夫人掌权以前，各家族已经有自己的规矩，但各自标准无法约束其他家族，争斗因此不断。约六十年前的黑暗时期，家族相互消耗，西西里夫人介入并建立灰厅，将各家秩序统一到自己认可的标准之下。她保留家族体系，却要求各家都在这一共同秩序中活动，限制无止境的相互毁灭。\n\n法院成为这套制度的执行机关。每座城市都有法院，法官代表灰厅意志，职责包括监视和预防十二家族之间的斗争。法官在地方仍可能受制于家族，却拥有不可轻易抹去的上层权威；家族也知道自己的行动始终受到西西里夫人监视。法律因此能约束一部分暴力，却仍依赖一位统治者及其维持的平衡。她从拉特兰带回铳与秩序的说法，也被叙拉古人反复讲述，但既有家族并未由此转成普通的公共行政机关。","people":["西西里夫人","阿格尼尔","贝纳尔多","拉维妮娅"],"refs":[{"label":"叙拉古人·IS-8 · 行动前 危如累卵","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act21side/level_act21side_08_beg.txt","evidence":"game"},{"label":"叙拉古人·IS-9 · 行动后 文明的谎言","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act21side/level_act21side_09_end.txt","evidence":"game"},{"label":"叙拉古人·IS-4 · 行动后 苦夜惊雷","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act21side/level_act21side_04_end.txt","evidence":"game"},{"label":"叙拉古人·IS-ST-1 · 幕间 沉疴","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act21side/level_act21side_st01.txt","evidence":"game"}]},{"id":"siracusa-municipal-purge","period":"约三十年前至当代故事之前","title":"市政改革受挫与既有秩序延续","body":"灰厅形成后，试图改变家族统治的人仍然存在。卢比奥回顾三十年前的一批青年：他们相信可以让叙拉古脱离家族掌控，又因找不到广泛支持而用利益争取数个家族合作。后来市政大厅发生清洗，工作人员集体消失，办公间留下血迹；外界没有公开说明，过了一段时间，新的人员重新填满原来的岗位。卢比奥以此解释，政府可以被替换，而支配政府的家族秩序仍然延续。\n\n这段记忆说明，叙拉古在现有篇章开始前已经经历过公共权力改革的失败。法院的权威、官员的职位和普通人的生活，并不具有同样的安全保障。多年后，拉维妮娅虽能依托贝洛内背景惩处家族成员，却也承认法律依赖西西里夫人，而非被普遍接受的公平。德克萨斯家族的变故和沃尔西尼新城计划，将在这一延续数十年的制度背景中发生。","people":["卢比奥","拉维妮娅","西西里夫人"],"refs":[{"label":"叙拉古人·IS-8 · 行动后 危如累卵","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act21side/level_act21side_08_end.txt","evidence":"game"},{"label":"叙拉古人·IS-3 · 行动后 万箭所指","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act21side/level_act21side_03_end.txt","evidence":"game"},{"label":"叙拉古人·IS-2 · 行动前 荣誉之人","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act21side/level_act21side_02_beg.txt","evidence":"game"}]}]},"leithanien":{"id":"leithanien","intro":"莱塔尼亚的国家起源是一份能够演奏、也能实际作用于人的盟约。千年来，金律乐章、选帝侯与高塔知识共同维系帝国；叙拉古脱离、巫王改制和双子女皇即位，先后改变了这一结构。","scope":"从十部族盟约与选帝侯建制，写至巫王统治及被推翻后的二十余年；止于沃伦姆德、维谢海姆与1100年庆典等现有篇章开始之前。","chronologyNote":"早期盟约仅能确认为一千多年前，叙拉古独立纷争为一百多年前。巫王死亡以1100年叙事所回顾的二十三年前定位；四皇会战在本篇采用统治期内的相对顺序，不以活动发布时间代替事件年份。有关双子出身只采用原文确认的术式塑造，不采用敌对者的邪恶血统传言。","periods":[{"id":"leithanien-founding-covenant","period":"一千多年前","title":"十部族盟约与选帝侯建制","body":"来自不同部落的先贤在一位强大的不死术师见证下签订盟约，十个原本缺少共同文化认同的地区由此联系起来。盟约以金律乐章的形式存在，规定部族间关系，确立选帝侯制度，也为共同生活提供道德与审美标准。莱塔尼亚因这套共同规则成为国家，而不是先有一个统一王朝，再向各地分派相同制度。\n\n金律乐章既是可以演奏的作品，也是历代源石技艺大师把力量融注其中形成的巨大术式。它对个人与社会的影响并不限于庆典礼仪；金律法卫的力量及其对国家意志的服从，同样与乐章相连。巫妖长期在高塔保存、传授知识，与先祖有不干涉国家的约定。后世往往只看到高塔中的权威，却逐渐忘记其中一些学者本来就是萨卡兹。","people":["弗莱蒙特"],"refs":[{"label":"崔林特尔梅之金·ZT-4 · 行动后 狂想曲“望想” ","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act29side/level_act29side_04_end.txt","evidence":"game"},{"label":"崔林特尔梅之金·ZT-5 · 行动后 奏鸣曲“秋日” ","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act29side/level_act29side_05_end.txt","evidence":"game"},{"label":"崔林特尔梅之金·ZT-9 · 行动前 幻想曲“赠答” ","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act29side/level_act29side_09_beg.txt","evidence":"game"},{"label":"崔林特尔梅之金·ZT-5 · 行动前 奏鸣曲“秋日” ","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act29side/level_act29side_05_beg.txt","evidence":"game"}]},{"id":"leithanien-witch-king-revision","period":"一百多年前的叙拉古独立纷争与巫王即位初期","title":"叙拉古脱离与金律乐章更新","body":"共同乐章维持数百年后，叙拉古的独立行动使旧体系难以继续完整运作。失去一重旋律之后，各大区受到影响，延续数年的纷争把国家推向分裂。赫尔昏佐伦从选帝侯时期便研究这一问题，即位以后决定改写乐章，将已经离心的叙拉古部分删除，重新稳定剩余九个大区。\n\n弗莱蒙特为他准备观测与共振装置，却警告他，改写面对的并非普通乐谱，而是千年前众多先贤的意志与法术。赫尔昏佐伦仍完成了挑战，这也是帝国创建以来金律乐章唯一一次被修改。此举解决了具体的存续危机，也证明个人可以凌驾于被视为永恒的国家规则之上，为巫王随后高度集中的统治提供了条件。","people":["巫王","弗莱蒙特"],"refs":[{"label":"崔林特尔梅之金·ZT-4 · 行动后 狂想曲“望想” ","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act29side/level_act29side_04_end.txt","evidence":"game"},{"label":"崔林特尔梅之金·ZT-4 · 行动前 狂想曲“望想” ","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act29side/level_act29side_04_beg.txt","evidence":"game"},{"label":"崔林特尔梅之金·ZT-9 · 行动前 幻想曲“赠答” ","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act29side/level_act29side_09_beg.txt","evidence":"game"}]},{"id":"leithanien-war-and-tyranny","period":"巫王统治时期","title":"对外战争胜利与国内暴政发展","body":"巫王曾战胜高卢的科西嘉一世，阻止莱塔尼亚沦为其附庸。后来支持复归的人把这类功绩与乐章更新一起列为他拯救国家的证据，但原文中的争论也明确指出，这些功绩不能抵消他对萨卡兹和莱塔尼亚人的大规模戕害。国家在他手中维持了对外力量，国内个人却不断成为研究、支配与牺牲的对象。\n\n有音乐天赋的年轻人被集中关押，长期不停创作，以把最好的旋律送入始源之塔；不明原因的失踪和死亡成为幸存者记忆的一部分。研究留下的危险术式又能经由追随者继续流传。由此形成的反抗并非只有贵族争夺皇位，也有学者、士兵与普通受害者为结束暴政而采取行动。","people":["巫王","弗莱蒙特","格哈德"],"refs":[{"label":"崔林特尔梅之金·ZT-5 · 行动前 奏鸣曲“秋日” ","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act29side/level_act29side_05_beg.txt","evidence":"game"},{"label":"崔林特尔梅之金·ZT-3 · 行动后 练习曲“奇遇”","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act29side/level_act29side_03_end.txt","evidence":"game"},{"label":"崔林特尔梅之金·ZT-9 · 行动前 幻想曲“赠答” ","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act29side/level_act29side_09_beg.txt","evidence":"game"}]},{"id":"leithanien-fall-of-witch-king","period":"1100年叙事回顾的二十三年前","title":"始源之塔决战与双子女皇即位","body":"反抗最终汇集到巫王的高塔。弗莱蒙特提供了塑造双子的术式；参加行动的并非只有后来登上权力位置的人，大批年轻人、术师和士兵在战斗中死亡。洛里斯是第一个冲入高塔的士兵，格哈德身负重伤，康复后才知道同学、朋友和爱人已不在世。珂拉也在那一夜失去视力。\n\n巫王在这场政变中死亡，双子女皇随后执掌国家。新政权授予部分参与者爵位和职责，洛里斯成为子爵并统领崔林特尔梅宪兵。牺牲者得到纪念，巫王时代的血肉雕塑所在之处后来建成公园。然而，参与推翻暴君的人并没有因此获得一致的结局：有人进入政府，有人带着伤病退出，有人继续追问自己付出的代价究竟改变了什么。","people":["伊维格娜德","赫琳玛特","弗莱蒙特","格哈德","洛里斯"],"refs":[{"label":"崔林特尔梅之金·ZT-5 · 行动前 奏鸣曲“秋日” ","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act29side/level_act29side_05_beg.txt","evidence":"game"},{"label":"崔林特尔梅之金·ZT-1 · 行动后 清唱“晴空之歌”","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act29side/level_act29side_01_end.txt","evidence":"game"},{"label":"崔林特尔梅之金·ZT-2 · 行动后 序曲“哨兵” ","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act29side/level_act29side_02_end.txt","evidence":"game"},{"label":"崔林特尔梅之金·ZT-4 · 行动后 狂想曲“望想” ","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act29side/level_act29side_04_end.txt","evidence":"game"},{"label":"崔林特尔梅之金·ZT-ST-3 · 幕间 尾奏“晚霞” ","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act29side/level_act29side_st03.txt","evidence":"game"}]},{"id":"leithanien-postwar-order","period":"双子女皇即位以后，当代地方危机以前","title":"新宫廷建立与旧社会问题延续","body":"双子女皇建立新的宫廷权威，但选帝侯、高塔与地方贵族仍是国家运转的重要部分。二十三年前的站队改变了一些家族地位：过去服务贵族的家庭可能得到拔擢，旧贵族则不断受到与巫王关系有关的怀疑。普通人的教育机会是数百年争取的结果，并不会因君主更替便自动稳固；关于身份、知识与资格的冲突仍会在大学和地方社会重现。\n\n另一方面，巫王追随者并未全部消失，幸存者也没有统一的历史判断。格哈德用二十年研究金律乐章，却发现部族差异和阶层鸿沟远早于巫王，也未随他的死亡消除。流散的实验遗产、地方感染者处境以及新政权的监管方式，共同构成沃伦姆德和维谢海姆故事的既有背景。前史至此结束，后续篇章再记录这些问题怎样引发具体危机。","people":["伊维格娜德","赫琳玛特","格哈德","莱辛"],"refs":[{"label":"崔林特尔梅之金·ZT-4 · 行动后 狂想曲“望想” ","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act29side/level_act29side_04_end.txt","evidence":"game"},{"label":"崔林特尔梅之金·ZT-1 · 行动前 清唱“晴空之歌”","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act29side/level_act29side_01_beg.txt","evidence":"game"},{"label":"崔林特尔梅之金·ZT-5 · 行动前 奏鸣曲“秋日” ","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act29side/level_act29side_05_beg.txt","evidence":"game"}]}]},"columbia":{"id":"columbia","intro":"哥伦比亚先经历脱离维多利亚的独立战争，再以联邦治理、移民拓荒和科研投资迅速扩张。莱茵生命与升空计划出现时，这个新国家已经积累了关于开拓、国家力量及个人代价的长期矛盾。","scope":"从独立战争及联邦权力形成，写至海外干涉、拓荒社会与莱特夫妇的航空探索；结束于莱茵生命创立及后续现有篇章之前。","chronologyNote":"本篇不从主观地理条目补写殖民设立年、宣告独立日或具体战役日期。独立战争、国家建立及后续发展的先后有原文依据；军方四十年代行动来自游戏调查报告。拓荒者家庭和航空探索属于独立后社会发展的不同侧面，缺少可直接逐年对齐的日期，不将其写成互为因果的连续事件。","periods":[{"id":"columbia-independence-war","period":"联邦成立以前的独立战争时期","title":"脱离维多利亚与独立战争转折","body":"哥伦比亚可确认的国家形成史，始于开拓区脱离维多利亚的战争。恩希欧迪斯回顾诸国近代关系时，明确提到高卢支持哥伦比亚独立；《孤星》的调查报告又记载，独立军曾接近崩溃，在马克·麦克斯参与指挥后才扭转局面，迫使维多利亚公爵退走，奠定国家独立的基础。这个过程先于后来高卢在四皇会战中的覆灭，不能把两场战争合写成一次建国行动。\n\n胜利并没有使所有参战者获得相同结果。伍德洛与克里夫等人在战争中分别作出选择，有人被俘并关入维多利亚设立的柯略斯战俘营，经历严重虐待，战后也长期受其影响。后来被称为黑钢老板或达维镇普通居民的人，曾经都是这场战争的参与者；国家独立的公共叙述与个人留下的创伤，自此同时存在。","people":["马克·麦克斯","伍德洛","克里夫"],"refs":[{"label":"风雪过境·BI-6 · 行动后 歧路","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act14side/level_act14side_06_end.txt","evidence":"game"},{"label":"孤星·综合调查数据库《一场对话》","url":"https://prts.wiki/w/%E5%AD%A4%E6%98%9F%2F%E7%BB%BC%E5%90%88%E8%B0%83%E6%9F%A5%E6%95%B0%E6%8D%AE%E5%BA%93#%E4%B8%80%E5%9C%BA%E5%AF%B9%E8%AF%9D","evidence":"game","note":"PRTS转载的游戏内调查报告正文，非泰拉大典主观条目；采用其中关于旧史的记载。"},{"label":"不义之财·CV-5 · 行动后 疑惑之影","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act28side/level_act28side_05_end.txt","evidence":"game"},{"label":"不义之财·CV-8 · 行动后 告别往昔","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act28side/level_act28side_08_end.txt","evidence":"game"}]},{"id":"columbia-federal-structure","period":"独立后，联邦治理形成时期","title":"总统制度与梅兰德组织形成","body":"独立以后，马克·麦克斯成为总统，梅兰德·塞勒涅退到幕后，建立基金会。政府、总统与基金会并非完全重合的机构，后来副总统与梅兰德之间还会不断调整话语权。麦克斯的真实形态是超级终端，这一国家核心机密与公众从媒体看到的总统形象并不相同，也解释了他能够长期执政的特殊条件。\n\n梅兰德组织的前身则与塞勒涅的孤儿院有关。来自不同国家、家庭背景各异的孩子被收容并共同使用塞勒涅的姓氏；他希望他们首先成为哥伦比亚的孩子。后来成长为特工的梅希亚记得，旧家庭留下的物品也可能被不经询问地改作实用工具。这种教育把共同国家身份置于出身之上，也把是否有益于开拓视为衡量事物的尺度，影响了基金会此后的行事方式。","people":["马克·麦克斯","梅兰德·塞勒涅","锡人","真言"],"refs":[{"label":"孤星·综合调查数据库《一场对话》","url":"https://prts.wiki/w/%E5%AD%A4%E6%98%9F%2F%E7%BB%BC%E5%90%88%E8%B0%83%E6%9F%A5%E6%95%B0%E6%8D%AE%E5%BA%93#%E4%B8%80%E5%9C%BA%E5%AF%B9%E8%AF%9D","evidence":"game","note":"PRTS转载的游戏内调查报告正文，非泰拉大典主观条目；采用其中关于旧史的记载。"},{"label":"孤星·CW-ST-3 · 幕间 留下的人","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act25side/level_act25side_st03.txt","evidence":"game"},{"label":"未许之地·UR-8 · 行动前 栖脚地","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act47side/level_act47side_08_beg.txt","evidence":"game"}]},{"id":"columbia-military-investment","period":"四十年代以后，独立国家的扩张时期","title":"玻利瓦尔干涉与军方科研投入","body":"国家建立后，哥伦比亚逐渐卷入跨国竞争。它与莱塔尼亚围绕玻利瓦尔展开长期角力，不再只是等待开发的边疆。游戏内调查报告指出，国防部在四十年代试图扩大当地影响，却使战争变得惨烈，也因此在联邦政府和联合议会面前失势，随后转而广泛投资科技公司，希望凭新武器恢复地位。\n\n技术由此不仅是民用工业的资源，也成为政治和军事竞争的工具。政府和议会会接收军方投入形成的成果，却不必因此归还其原有权力。后来的军备研发得到持续投入，研究者、承包企业与国家机关间形成紧密联系；但资助方对成果用途的要求，也会与科学家的目标发生冲突。莱茵生命并非这一结构的创造者，它后来进入的是已经形成数十年的科研资金与权力体系。","people":["锡人","杰克逊"],"refs":[{"label":"风雪过境·BI-6 · 行动后 歧路","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act14side/level_act14side_06_end.txt","evidence":"game"},{"label":"孤星·综合调查数据库《任务简报》","url":"https://prts.wiki/w/%E5%AD%A4%E6%98%9F%2F%E7%BB%BC%E5%90%88%E8%B0%83%E6%9F%A5%E6%95%B0%E6%8D%AE%E5%BA%93#%E4%BB%BB%E5%8A%A1%E7%AE%80%E6%8A%A5","evidence":"game","note":"PRTS转载的游戏内调查报告正文，非泰拉大典主观条目；采用其中关于旧史的记载。"},{"label":"孤星·CW-1 · 行动后 迷雾重重","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act25side/level_act25side_01_end.txt","evidence":"game"}]},{"id":"columbia-frontier-society","period":"独立后延续多代的拓荒与移民时期","title":"拓荒劳动与教育流动机会","body":"与城市里的科研投资并行，荒野上持续存在跨越数代的拓荒劳动。叙拉古家族在哥伦比亚初建时便派人进入开拓地，逐渐取得财富和势力；普通拓荒者则反复迁移，在天灾风险、临时基地与有限生活条件中谋生。社会流动的机会真实存在，却并不意味着所有参与者都能得到同等保障。\n\n多萝西的家庭呈现了这段社会史的一种具体情况。父亲在荒野行医，母亲继承拓荒者的生活；父母相信教育可以使女儿离开危险环境，于是为她攒下进入大学的费用。她获得理工大学夏令营邀请时，母亲所在临时基地却被天灾摧毁。这样的家庭经历发生在她成为研究者之前，显示拓荒一方面为城市和大学提供人力与资源，另一方面仍让劳动者承担可能无法挽回的风险。","people":["多萝西","萨尔瓦多雷·德克萨斯"],"refs":[{"label":"叙拉古人·IS-1 · 行动前 雨落无声","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act21side/level_act21side_01_beg.txt","evidence":"game"},{"label":"多萝西·档案资料二","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/excel/handbook_info_table.json","evidence":"game","note":"干员档案数据：char_4048_doroth，档案资料二。"}]},{"id":"columbia-light-aviation","period":"克丽斯腾童年及莱茵生命创立以前","title":"莱特夫妇飞行试验与探索遗产","body":"在这一鼓励技术进步、又对未知天空充满怀疑的社会中，莱特夫妇进行飞行研究。克丽斯腾年幼时曾随他们低空飞行，先在引擎声和颠簸中感到害怕，随后从空中看见地面，天空因此成为切身经验，而非书本中的抽象对象。夫妇后来在高空探索事故中死亡，他们的研究目标并未随之获得社会一致理解。\n\n雅拉受梅兰德派遣，曾为他们处理经费和外部威胁问题；她的日记将事故认定为意外，也记下死者受到同行讥讽和狂热者嘲弄的情况。她在葬礼上看到孩子一直仰望天空，此后决定给予帮助。克丽斯腾后来仍把父母留下的火光视为探索的起点。现有纪事从她与塞雷娅建立莱茵生命开始，这段航空旧史则解释了两人在公司创立以前已经面对的研究目标与代价问题。","people":["克丽斯腾","雅拉","塞雷娅"],"refs":[{"label":"孤星·CW-ST-1 · 幕间 阴云密布","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act25side/level_act25side_st01.txt","evidence":"game"},{"label":"孤星·综合调查数据库《一页日记》","url":"https://prts.wiki/w/%E5%AD%A4%E6%98%9F%2F%E7%BB%BC%E5%90%88%E8%B0%83%E6%9F%A5%E6%95%B0%E6%8D%AE%E5%BA%93#%E4%B8%80%E9%A1%B5%E6%97%A5%E8%AE%B0","evidence":"game","note":"PRTS转载的游戏内调查报告正文，非泰拉大典主观条目；采用其中关于旧史的记载。"},{"label":"孤星·CW-10 · 行动后 散于星辰之间","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act25side/level_act25side_10_end.txt","evidence":"game"}]}]},"laterano":{"id":"laterano","intro":"拉特兰的起源早于圣城、教廷和万国信使。萨科塔先从提卡兹中分化，继而在圣徒带领下筑塔建城；共感、成文法与跨境公民义务又逐步形成了后世的政治和宗教秩序。","scope":"从游戏所揭示的族群起源与圣城建立，写至长期公民制度、万国信使和首次峰会前的旧案；不重复峰会及其后的现有地区纪事。","chronologyNote":"族群分化的远古年代与圣城数千年的记述不可直接等同；不推算精确建国年。最初圣徒的故事由律法数据中的复现个体自述，正文标出叙述性质，不将其全部细节提升为无争议旁白。1069年由1099年信使制度三十周年推得；小队旧案以首次峰会八年前定位。","periods":[{"id":"laterano-ancestral-separation","period":"远古族群分化时期，早于圣城建立","title":"提卡兹远行与萨科塔起源","body":"《众生行记》揭示，萨科塔的起源与提卡兹有关。最初圣徒的数据复现体向能天使讲述：当族群在强敌进攻下失去生机时，魔王派出勇士寻找地下的银色山脉，希望借其力量退敌。远行者在荒原相互扶持，最终找到悬浮巨石、环状结构和沉睡的金属设施，却无法依靠既有语言使它回应。\n\n按这一自述，极度饥渴中一名成员违反禁令吞食同伴，设施随之启动，远行者身上出现光环与光翼，疲惫的身体重新获得力量。她将这一转化理解为求生祈祷得到回答。此后，获得新形态的群体离开了原有使命，逐渐形成萨科塔的身份。原文确认两族具有这段共同来处，但具体起因由携带自身信仰的复现个体解释；不能只因后世称其为圣徒，便把她关于救赎和使命的全部判断视作客观历史结论。","people":["能天使","送葬人"],"refs":[{"label":"众生行记·MT-8 · 行动后 朝圣","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act42side/level_act42side_08_end.txt","evidence":"game","note":"族群起源由律法中的圣徒数据复现体自述。"},{"label":"众生行记·MT-10 · 行动前 降生","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act42side/level_act42side_10_beg.txt","evidence":"game"}]},{"id":"laterano-city-foundation","period":"数千年前，初代圣徒行走时期","title":"启示石塔建造与拉特兰立城","body":"在拉特兰经典中，初代圣徒带领萨科塔跋涉，遭遇黑暗和追兵，许多人失去生命。随后圣徒筑起石塔，钟声使分散的人重新结成共同体，再围绕石塔建立作为萨科塔乐园的城市，并将其命名为拉特兰。启示石塔因此先于城市，是圣城最古老的建筑之一。\n\n这套建城记忆后来成为拉特兰的共同传统。千年来，圣徒之名不只是荣誉，也意味着引领全体萨科塔与城市的职责；在最初先贤之后，称号长期只随历任教宗代代相承。教廷的权威既来自宗教解释，也承接着筑城、保护共同体和维持秩序的历史责任。现有文本没有给出最初工程的施工年表，也未列全每一位建城者的个人履历。","people":["伊万杰利斯塔十一世","安多恩"],"refs":[{"label":"吾导先路·GA-6 · 行动后 安魂曲","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act16side/level_act16side_06_end.txt","evidence":"game"},{"label":"圣约送葬人·档案资料四","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/excel/handbook_info_table.json","evidence":"game","note":"干员档案数据：char_1032_excu2，档案资料四"}]},{"id":"laterano-civic-order","period":"建城以后，长期制度形成时期","title":"多族居民迁入与公民义务建立","body":"圣城后来容纳了不只萨科塔的居民。游戏回顾黎博利历史时，提到最初跟随驮兽而来的流民，以及此后对萨科塔生活和思维方式的学习。共同居住与共同信仰使他们成为拉特兰的一部分，但光环与共感并不能靠学习获得。能否共享同一种直觉联系，因而长期影响不同居民在政治、宗教及日常生活中的位置。\n\n国家同时建立了可以落实到具体事务的公民制度。公证所既向散居各地的拉特兰公民征收费用、督促履行抚养监护、遗产和契约义务，也为他们提供权益维护，派执行者赴其他城邦处理复杂事务。律法因此不只是教堂中的训诫，还通过记录、契约和外勤执行进入个人生活。这些机构的详细设立年份尚未公开，不能把后来的每一次制度调整都写成与建城同时完成。","people":["菲亚梅塔","送葬人"],"refs":[{"label":"众生行记·MT-7 · 行动前 丧礼","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act42side/level_act42side_07_beg.txt","evidence":"game"},{"label":"送葬人·档案资料一","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/excel/handbook_info_table.json","evidence":"game","note":"干员档案数据：char_279_excu，档案资料一"},{"label":"送葬人·档案资料四","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/excel/handbook_info_table.json","evidence":"game","note":"干员档案数据：char_279_excu，档案资料四"}]},{"id":"laterano-national-messengers","period":"1069年起，首次峰会以前","title":"万国信使设立与中立外交延伸","body":"在万国信使制度出现以前，拉特兰因其在核心国家间的特殊地位及中立立场，已经时常受托传递重大事件信息。本代教宗将这种临时外交工作常态化，建立专门队伍，以保持绝对中立为原则，促进国家间的重要信息流通。1099年迎来制度三十周年，因此其建立可定位于1069年。\n\n信使必须长期在各国旅行，接触与圣城内不同的制度、战争和生存环境。拉特兰的宗教与公民联系也由此获得新的实际渠道：人在境外活动，仍与国内机构保持职责关系。但中立并不意味着外部世界没有冲突，传递消息也不能自动消除利益差异。万国信使逐步建立的往来网络，后来才成为邀请诸国代表赴拉特兰讨论集体安全的组织基础。","people":["伊万杰利斯塔十一世","莫斯提马","奥伦"],"refs":[{"label":"吾导先路·GA-ST-1 · 幕间 风云际会","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act16side/level_act16side_st01.txt","evidence":"game"}]},{"id":"laterano-squad-rupture","period":"首次峰会八年前至1098年","title":"小队旧案与峰会召集准备","body":"首次峰会八年前，一支包含安多恩、莫斯提马、蕾缪安和菲亚梅塔的小队在外执行清剿任务。菲亚梅塔因后来被确认是陷阱的虚假支援消息离开，数小时后返回废墟，已经无法挽回变化：蕾缪安被安多恩的技艺重伤并长期昏迷，莫斯提马为阻止他夺走锁与匙而举铳，随后堕天离城。安多恩离开原有队伍，其资料不再出现在公开的官方文件中。\n\n事件之后，各人的职责分开延续。菲亚梅塔离开不能长期外派的戍卫队，挂靠公证所，随莫斯提马行动，同时坚持追究旧案；莫斯提马继续对外工作，蕾缪安则经历漫长疗养。这场内部断裂先于峰会，并未由中立外交或萨科塔的共感自行化解。1098年，教宗通过万国信使向诸国发出集体安全会议邀请；到次年使节到来时，这些旧案与更大的国家议程一同进入现有地区纪事。","people":["安多恩","莫斯提马","蕾缪安","菲亚梅塔","伊万杰利斯塔十一世"],"refs":[{"label":"菲亚梅塔·档案资料四","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/excel/handbook_info_table.json","evidence":"game","note":"干员档案数据：char_300_phenxi，档案资料四"},{"label":"吾导先路·GA-4 · 行动后 安魂教堂","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act16side/level_act16side_04_end.txt","evidence":"game"},{"label":"吾导先路·GA-7 · 行动前 光与影","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act16side/level_act16side_07_beg.txt","evidence":"game"},{"label":"吾导先路·GA-ST-1 · 幕间 风云际会","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act16side/level_act16side_st01.txt","evidence":"game"}]}]},"iberia":{"id":"iberia","intro":"伊比利亚在大静谧以前已经是拥有王族、贵族、国教会和远洋舰队的国家。其兴盛既包括跨大陆的扩张，也包括与阿戈尔岛民合作形成的海洋技术体系。布雷奥甘参与的灯塔与巨舰建设，把王国的航海事业和阿戈尔人的返乡研究连在一起。","scope":"从游戏能够追述的旧王国建制写到1038年灾难以前的黄金时代与远航准备，后续大静谧、海岸封闭及清洗由现有纪事承接。","chronologyNote":"现有游戏追述未给出足以核实的最初建国年与首任君主。1011年修道院工程、1038年大静谧有明确文本依据；帝国扩张与技术合作并非都能精确排序，不把它们合并为同一个建国事件。","periods":[{"id":"iberia-old-royal-order","period":"确切年代未明的旧王国时期","title":"王族、贵族与国教会","body":"旧伊比利亚并不是自始就由今天所见的审判庭独掌一切。阿方索回顾自身身份时，称自己是旧伊比利亚的公爵、大舰队总指挥和斯图提斐拉号船长；他也明确区分王族与国教会，甚至讥讽教会曾无力约束王族。王室、贵族军事力量与宗教机构因而是不同的权力来源，不能将灾难之后的国家形态直接套回全部旧史。\n\n国家曾经拥有发达的对外交往。卡门年轻时随导师接待卡西米尔来使，也见过舰队出航和维多利亚使节，说明其政治视野远不止后来封闭的海岸。国教会保有与拉特兰教的历史联系，但伊比利亚社会并非每个人都信仰同一宗教。所读追述能够确认这些制度已经存在，尚不能据此补出一个单一的立国仪式或精确开国年代。","people":["阿方索","卡门","极境"],"refs":[{"label":"愚人号·SN-ST-6 · 幕间 下层大厅","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act17side/level_act17side_st06.txt","evidence":"game"},{"label":"愚人号·SN-ST-1 · 幕间 古井","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act17side/level_act17side_st01.txt","evidence":"game"},{"label":"愚人号·SN-4 · 行动后 灯塔入口","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act17side/level_act17side_04_end.txt","evidence":"game"},{"label":"愚人号·SN-1 · 行动后 中心广场","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act17side/level_act17side_01_end.txt","evidence":"game"}]},{"id":"iberia-aegir-technology","period":"黄金时代的海陆技术合作","title":"岛民工艺与灯塔舰船建设","body":"阿戈尔人布雷奥甘在黄金时代成为王公贵族的座上宾，一度被寄望于开启岛民与伊比利亚人和谐共处的新阶段。他帮助王族建立灯塔和舰队，将阿戈尔的海洋通讯与工艺带入陆地国家的建设。相关遗稿还尝试结合源石能源、移动城市经验与阿戈尔技术；这些并不都等于已经全面实现的城市工程，需要同实际建成的设施分别看待。\n\n伊比利亚之眼不只是照明装置，也是能够联通信号的终端。巨舰中同样藏有阿戈尔式发信设备，舰船和灯塔由此构成配套体系。对王国而言，这些设施支持航行和海上事业；对布雷奥甘而言，建设它们也有重新联系故乡的目的。工程合作于是同时包含国家需求、移民处境与研究者的个人目标。后来留存的钥匙、图纸和通讯装置，正来自这一阶段。","people":["歌蕾蒂娅","乌尔比安","卡门"],"refs":[{"label":"愚人号·SN-6 · 行动前 中央通道","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act17side/level_act17side_06_beg.txt","evidence":"game"},{"label":"愚人号·SN-5 · 行动前 灯塔控制室","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act17side/level_act17side_05_beg.txt","evidence":"game"},{"label":"愚人号·SN-10 · 行动前 礼仪广场","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act17side/level_act17side_10_beg.txt","evidence":"game"},{"label":"愚人号·SN-ST-8 · 幕间 指挥大厅","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act17side/level_act17side_st08.txt","evidence":"game"}]},{"id":"iberia-golden-expansion","period":"国力鼎盛及1011年的对外合作","title":"远征扩张与跨国往来","body":"伊比利亚的黄金时代并不只有海岸财富。卡门明确提到，国家鼎盛时曾跨越大陆向玻利瓦尔平原进军，金币与知识一同流入城市。军事扩张、贵族声望和远航事业在这一时期相互支撑。由于所读文本没有给出该次扩张的确切年代，不能把它直接解释为某一批阿戈尔工匠到来之后立即发生的结果，也不能据此替换更早的王国历史。\n\n跨国联系还体现为宗教与公共设施的合作。1011年，伊比利亚与拉特兰合资建造可移动的大型综合设施安布罗修修道院，正式属国为伊比利亚。后来的修道院居民仍把其中培育的特殊花卉视作双方友谊与希望的象征。这样的工程表明，在长期封闭成为人们最鲜明的印象以前，伊比利亚有能力与外部国家共同筹建、运行复杂设施；宗教联系也不只是后来对于援助与责任的争执。","people":["卡门","费德里科"],"refs":[{"label":"愚人号·SN-ST-1 · 幕间 古井","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act17side/level_act17side_st01.txt","evidence":"game"},{"label":"空想花庭·HE-ST-1 · 幕间 奉上冠冕","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act26side/level_act26side_st01.txt","evidence":"game"},{"label":"空想花庭·HE-ST-2 · 幕间 在花园里","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act26side/level_act26side_st02.txt","evidence":"game"}]},{"id":"iberia-last-voyage-prelude","period":"1038年大静谧以前的远航末期","title":"黄金舰队与最后的出航准备","body":"斯图提斐拉号集中体现了旧时代的资源投入：它满载学者与军人，也是王族的海上行宫，内部有广阔大厅、雕塑、精细织物和繁复装饰。阿方索所记得的出航，伴随欢呼与礼炮，船员带着有关阿戈尔的传说驶向更深的海域。国家把探索、研究、军事力量与贵族生活一同放上巨舰，远航因而是社会繁荣的展示，也是对海洋尚未被充分理解的信心。\n\n布雷奥甘留下的研究则指向繁荣背后的未知。他在陆地上寻找解释海洋灾祸的线索，将相关结论藏入巨舰及私人记录；这些内容后来比装饰和财富更受阿戈尔研究者重视。出航后的船员并不知道，这套耗费巨大资源建成的体系即将遭遇无法按既有经验处置的危机。阿方索后来只记得，离岸仅数日灾难便来临。其后发生的大静谧与国家转折，由现有纪事继续叙述。","people":["阿方索","歌蕾蒂娅","乌尔比安"],"refs":[{"label":"愚人号·SN-6 · 行动前 中央通道","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act17side/level_act17side_06_beg.txt","evidence":"game"},{"label":"愚人号·SN-7 · 行动后 黄金回廊","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act17side/level_act17side_07_end.txt","evidence":"game"},{"label":"愚人号·SN-ST-8 · 幕间 指挥大厅","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act17side/level_act17side_st08.txt","evidence":"game"},{"label":"愚人号·SN-ST-9 · 幕间 主舰桥","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act17side/level_act17side_st09.txt","evidence":"game"}]}]},"aegir":{"id":"aegir","intro":"阿戈尔的前史不始于深海猎人。游戏追述把其文明经验上推至数千年前的海洋中心探索，随后形成形态多样的海上与海底城市、公共知识设施及专业分工。海嗣战争逐渐改变这套社会，跨洋航道与深海猎人则是不同阶段提出的存续方案。","scope":"叙述阿戈尔文明记忆、城市制度与战争前的技术路线，止于深海猎人远征以前；不重复登陆、盐风城重聚及《生路》的返乡行动。","chronologyNote":"“数千年前”“两百多年前”等采用人物明确追述，不补造统一建国年。文明原点的含义尚未完整公开；乌尔比安的推论、旧技术方案与已建成制度分别记述，不将假想海嗣未来并入历史。","periods":[{"id":"aegir-ocean-origins","period":"数千年前的海洋中心探索","title":"海洋探索与文明原点","body":"乌尔比安回顾阿戈尔通识历史时，提到先人曾在数千年前抵达海洋中心，并在那里发现被称为“文明的原点”的事物。这是游戏中能够明确上溯的集体历史记忆，但原文并没有同时给出国家成立的年份、第一位执政官或完整迁徙路线。文明原点也不能直接按字面改写为某一座已确认的建国城市；它与深海异常遗构的联系，仍属于人物继续调查的内容。\n\n海洋长期构成阿戈尔发展的环境条件。乌尔比安将它比作保护文明的培养皿，指出源石和天灾难以侵袭阿戈尔的若干推论曾得到证实。相较于依靠源石开发、又受其反噬的陆地社会，阿戈尔形成了自己的技术经验和自我认识。这样的海陆分流是后来双方互不理解的重要背景，却不表示每个阿戈尔人在任何地方都不会感染矿石病。","people":["乌尔比安","歌蕾蒂娅"],"refs":[{"label":"愚人号·SN-ST-8 · 幕间 指挥大厅","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act17side/level_act17side_st08.txt","evidence":"game"}]},{"id":"aegir-cities-and-knowledge","period":"城市网络与公共制度形成以后","title":"城市网络与专业分工","body":"阿戈尔逐渐建成不同形态的城市：海面上有相互支撑的环礁城市群，海沟下有模块化城市网络，其他城市也各有设计。城市运行依靠穹顶、环境管理、自动机械和专业机构共同维持，并非一座王宫可以代表的单一聚落。公共养育所承担照护与教育，发展规划所进行职业评估，人们再进入技术、科学、艺术等工作领域。\n\n这些制度并非只为军队服务。卢契拉幼时参加过将神经活动转为光学矩阵的演出，劳伦缇娜父母设计的穹顶也能与表演机械互动；生态艺术工作者培育深海藻类，使其生长成不断变化的作品。她们后来如何转岗、为何失去原来的生活，只有放在这种曾容许多样兴趣与职业的社会基础上才可理解。城市设施同时承担生存保障、知识传播和文化生活的功能。","people":["海霓","幽灵鲨"],"refs":[{"label":"生路·BP-2 · 行动前 评议式迎接","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act34side/level_act34side_02_beg.txt","evidence":"game"},{"label":"生路·BP-6 · 行动前 阿戈尔失格","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act34side/level_act34side_06_beg.txt","evidence":"game"}]},{"id":"aegir-forums-and-seaway","period":"两百多年前以来的公共思想与远航方案","title":"斗智场与跨洋技术设想","body":"两百多年前，人类学家暨先史文明研究者玛利图斯提出并主持建设斗智场。其核心为储存知识、文化与未解问题的集成终端，市民可在这里思考、辩论并形成决定。这种设计被多个城市采用，后来不仅用于学术交流，也成为跨领域评议公共事务的场所。玛利图斯消失后，设施和研究传统继续运行，其学说仍影响后世执政者理解国家的道路。\n\n同样上溯到约两百年前的，还有以微型浮游机械构成跨洋通路的方案。旧设想需要多座城市共同供能、持续孵化机械，再以机械间的信息流支持跨海移动，规模和能源要求都很高，当时未能延续。它说明阿戈尔早已考虑超越分散城市的交通限制，而非直到猎人失散后才想到离开家乡。此后的航道工程沿用部分旧思路，实际条件和承担风险的人群却发生了变化。","people":["乌尔比安","歌蕾蒂娅"],"refs":[{"label":"生路·BP-2 · 行动前 评议式迎接","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act34side/level_act34side_02_beg.txt","evidence":"game"},{"label":"生路·BP-8 · 行动前 “何谓存续？”","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act34side/level_act34side_08_beg.txt","evidence":"game"}]},{"id":"aegir-war-reorientation","period":"海嗣战争扩大至深海猎人远征以前","title":"战争动员与深海猎人计划","body":"海嗣持续扩张、适应攻击的特性，逐渐迫使阿戈尔把更多研究、设施与人员转向战争。维持城市生活的机构必须参与防御，艺术家和普通技术人员也会因岗位重组离开原来的事业。军事决策因而不仅关乎舰队胜负，还改变了每个城市能够继续提供怎样的生活。国家尊重同胞价值的理念，与为整体存续接受牺牲的选择，在这一阶段不断发生冲突。\n\n常规打击难以彻底终止海嗣演化，深海猎人计划遂尝试将敌人的生理特征引入人体，培养能潜入巢穴近身作战、又保有自我意识的战士。歌蕾蒂娅和乌尔比安既参与战争设计，也承担了相关研究与改造的后果，斯卡蒂、劳伦缇娜等人则成为不同队伍的猎人。至此，现有纪事才进入远征与失散的起点：猎人是国家长期应战中的一条技术路线，不能代替阿戈尔全部的文明史。","people":["乌尔比安","歌蕾蒂娅","斯卡蒂","幽灵鲨"],"refs":[{"label":"生路·BP-1 · 行动后 第一次接触","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act34side/level_act34side_01_end.txt","evidence":"game"},{"label":"生路·BP-2 · 行动前 评议式迎接","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act34side/level_act34side_02_beg.txt","evidence":"game"},{"label":"生路·BP-6 · 行动前 阿戈尔失格","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act34side/level_act34side_06_beg.txt","evidence":"game"},{"label":"愚人号·SN-ST-8 · 幕间 指挥大厅","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act17side/level_act17side_st08.txt","evidence":"game"}]}],"absorbedPhases":{}},"sargon":{"id":"sargon","intro":"萨尔贡的历史不能只用一座黑市或一片雨林概括。游戏中的古史由王者传记、宫廷史官、宝石工艺、城市遗址与部族传统交错保存。路加萨尔古斯的征服与南征是其中重要转折，但并非已被证实的最初建国事件；其后的地方社会仍保持显著差异。","scope":"从路加萨尔古斯以前已有的古史记忆，写至王朝继承、辉煌之城形成及阿卡胡拉传统秩序，为黑市、雨林与城市三条现代支线提供前提。","chronologyNote":"所读游戏材料没有提供可独立核验的统一建国年，不把路加萨尔古斯直接写成开国君主。祖拜尔记忆经幻境展示，并有史官家族档案佐证；雨林传统与古代宫廷事件的确切先后未明，分层记述。","periods":[{"id":"sargon-early-historical-records","period":"路加萨尔古斯以前及古史编纂的起点","title":"古代国家与史官传统","body":"萨尔贡在路加萨尔古斯的子女成长时，已经拥有更为久远的历史。祖拜尔的姐姐翻检抄本和记录后，发现前代事迹多有遗漏，因而打算编成一部能够完整记述国家历史的史籍，获得父亲支持。这段回忆首先确认：名王的生涯并不等于国家的全部开端，其之前已经存在政治生活和文本传承，只是现存记录并不完整。\n\n后来的博物馆还保存分属古历纪不同时代的雕塑、乐器及工艺遗存，不能将它们都归到同一位君王名下。佩佩家族的祖先跟随路加萨尔古斯征战，以灯芯草笔记事；此后家族逐代选人随侍万王之王，持续形成《萨尔贡史》。宫廷史书因而有明确的传承机构，也有接近权力中心的条件，但它不是没有取舍的完整记录，地方遗址与普通人的遗物仍能补出史书之外的生活。","people":["佩佩","祖拜尔"],"refs":[{"label":"太阳甩在身后·AS-8 · 行动后 黄沙尽头","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act35side/level_act35side_08_end.txt","evidence":"game"},{"label":"太阳甩在身后·AS-ST-1 · 幕间 辉煌之城","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act35side/level_act35side_st01.txt","evidence":"game"},{"label":"游戏本体档案·佩佩·档案资料二至四","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/excel/handbook_info_table.json","evidence":"game","note":"使用char_4058_pepe条目的家族史与考古记录。"}]},{"id":"sargon-shah-and-nightzmora","period":"路加萨尔古斯在位与梦魇到来时期","title":"王权整合与南征决策","body":"路加萨尔古斯统治的年代，中央王权必须不断面对部族的反叛和挑战。他率军重整队伍、压服对手，王子祖拜尔也通过战功成长，后来统领父亲的卫戍部队。君王、王室子女、将领与地方部族之间的关系，构成了当时统治运行的具体层次；这并不是所有地区生活都由同一套城市行政直接管理的结构。\n\n来自东方的梦魇哈兰杜汗改变了君王此后的选择。交手激起了路加萨尔古斯罕见的热情，他转而邀请对方一同南下，挑战焚风热土的无形敌人。当时这些敌人已侵蚀土地，祖拜尔也决定参加。南征因此既有两名强者之间的联系，也有实际的边境威胁，不能只写成争强好胜的游历；但战役如何展开、君王最终去了哪里，所读回忆没有给出足以补齐全过程的答案。","people":["佩佩","祖拜尔"],"refs":[{"label":"太阳甩在身后·AS-8 · 行动后 黄沙尽头","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act35side/level_act35side_08_end.txt","evidence":"game"},{"label":"游戏本体档案·佩佩·档案资料三","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/excel/handbook_info_table.json","evidence":"game","note":"条目char_4058_pepe，记录沙阿、哈兰杜汗及未决去向。"}]},{"id":"sargon-succession-and-guardians","period":"南征失踪与王位继承以后","title":"王朝继承与宝库守护","body":"路加萨尔古斯失去踪迹后，王兄继位，祖拜尔重伤归来，身上没有完好的皮肤。他与新君并非同母，军中功绩又招来忌惮，仍无法安心休养；西南部族重新举兵，也使他希望继续履行军事职责。宝石匠人提出以特殊回路保留意识，长生军工匠则制作新的躯壳，祖拜尔因此接受不可逆的改造。\n\n与此同时，姐姐与史官继续编书，并准备让后代承继工作。她选择以笔保存父亲事迹，祖拜尔则修建衣冠冢、守护宝库，等待梦魇后裔领取君王承诺留下的珍藏。两种纪念方式后来分别形成史官制度与长期封存的守护职责。宫廷亲属间的感情、皇位继承的猜疑和国家军事需要在这里相互牵连，也说明古代宝石技术并不只是供人佩戴的装饰工艺。","people":["祖拜尔","佩佩"],"refs":[{"label":"太阳甩在身后·AS-8 · 行动后 黄沙尽头","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act35side/level_act35side_08_end.txt","evidence":"game"}]},{"id":"sargon-city-over-treasury","period":"此后数百年的地方城市发展","title":"宝库遗址与辉煌之城形成","body":"米纳特哈玛仪后来建在宝库和衣冠冢之上。数百年间，人们持续向地下发掘，把取得的文物与珍宝转化为城市财富；古王的遗产并未始终保持封闭，而是逐渐进入住宅、交易和公共设施。祖拜尔所守护的最深层珍藏则一直没有被触及。城市之所以富饶，与这段长期开掘和再利用的历史直接相关。\n\n水利和宝石工艺共同支撑定居生活。居民自豪于已有四百年历史的河道和两百年的建筑，部分宝石刻有能够净化水源的回路；博物馆则长期获得王酋、帕夏支持，不必单靠门票获利。漫灌节保留被称为来自千年前的传统，居民向河中献上花朵、杯盏和酒。古代陵寝、地方权贵、工程设施和节庆由此叠合成城市，辉煌之城不是整个萨尔贡的唯一历史中心。","people":["佩佩","祖拜尔","缇缇"],"refs":[{"label":"太阳甩在身后·AS-8 · 行动后 黄沙尽头","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act35side/level_act35side_08_end.txt","evidence":"game"},{"label":"太阳甩在身后·AS-ST-1 · 幕间 辉煌之城","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act35side/level_act35side_st01.txt","evidence":"game"}]},{"id":"sargon-rainforest-orders","period":"现代返乡故事以前的阿卡胡拉传统","title":"雨林部族与大酋长制度","body":"在阿卡胡拉，维系诸部族秩序的是另一套传统。部族定期举行名为玛维索提亚的祭典，通过公开战斗选出得到其他人认可的挑战者，再由其挑战现任大酋长。首领不在时，就重新举行祭典；据当地人转述，许多大酋长两三年便更替，胡安在位相对长久。这里的政治承认来自部族内部的力量展示与认可，不能直接套成黄金之城的宫廷继承。\n\n嘉维尔离乡以前的一次祭典未能选出新首领，各部族随后互不服气，斗争加剧，部分群体进一步进入原本居住较分散的雨林。祖玛玛则凭机械知识增强森蚺部族的影响。这些变化构成返乡篇章的前提，而非一次全国性政权更迭。萨尔贡的中央君王、地方帕夏与王酋、古城贸易和雨林祭典因此应分层理解，各地社会没有在漫长历史中变成同一种制度。","people":["嘉维尔","特米米","森蚺"],"refs":[{"label":"密林悍将归来·RI-1 · 行动后 高空坠物","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act12d0/level_act12d0_01_end.txt","evidence":"game"},{"label":"密林悍将归来·RI-2 · 行动前 粗细有别","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act12d0/level_act12d0_02_beg.txt","evidence":"game"}]}]},"siesta":{"id":"siesta","intro":"汐斯塔是一座只有数十年城市史的独立城邦。游戏可追述的前史，始于火山黑曜石矿业及工人聚居，随后经过矿业限制、旅游转型和音乐节扩张。芭芭拉的矿工照护工作与赫尔曼的城市经营，也在这一过程中形成。","scope":"从旧汐斯塔的矿业生活写到《火蓝之心》开始前的度假城市，不重复音乐节调查、迁入移动城市及《火山旅梦》的当代行动。","chronologyNote":"本篇依据后续人物回忆还原前史。赫尔曼只将城市历史概括为数十年，未核实确切建城年、首任市长及独立法律程序；矿业、照护与音乐活动有重叠，不强行编成年表。","periods":[{"id":"siesta-mining-settlement","period":"最早可考的黑曜石矿业时期","title":"火山开采与矿业聚落","body":"旧汐斯塔的发展与火山黑曜石开采密切相关。卡恩后来明确回顾，矿业曾是当地的主要经济来源；布朗家族经营矿场，佩利佩的父亲是矿主，工人靠开采维持家庭生活。矿石先是城市的收入来源，后来又成为收藏品、装饰品与旅游纪念物。早期矿业并非一段与度假城市完全无关的历史：此后仍住在城里的售票员、司机和保安中，就有失去原来工作的矿工。\n\n矿场也留下了感染和劳动问题。工人的安全知识多依赖经验，有人不识字，超负荷工作和矿石病却不会因为城市获得收入便消失。佩利佩后来继续收存品相并不精美的矿石，记得开采者付出的代价。赫尔曼把汐斯塔的城市史称为短暂的数十年；目前这些回忆能确认矿业支撑了城市成长，却没有提供足以精确标定建城之日的市政文书。","people":["赫尔曼","锡兰"],"refs":[{"label":"火山旅梦·SL-2 · 行动前 小蓝孩","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act27side/level_act27side_02_beg.txt","evidence":"game"},{"label":"火山旅梦·SL-7 · 行动前 靠着我的肩膀哭泣","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act27side/level_act27side_07_beg.txt","evidence":"game"},{"label":"火山旅梦·SL-7 · 行动后 靠着我的肩膀哭泣","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act27side/level_act27side_07_end.txt","evidence":"game"}]},{"id":"siesta-workers-care","period":"锡兰出生前后的早期城市发展阶段","title":"芭芭拉的矿工照护工作","body":"来自维多利亚的学者芭芭拉，在怀孕期间仍持续进入矿场，调查环境并帮助工人。她并不把感染者视为与普通人隔绝的一类，而希望自己将来的孩子也能生活在容许他们安稳工作、获得照顾的城市中。她尝试向矿工传授如何观察环境、避开危险，以及灾害发生后如何尽量自保的知识，并提出为因开采黑曜石而感染的人争取更好照护的法案设想。\n\n这项工作面对的困难并不只是医疗不足。年轻的矿业继承人曾告诉她，政府忙于筹钱发展城市，未必愿意顾及矿工；她仍决定把问题带到政府面前。汤姆、汉克和比尔等工人因此准备了一块黑曜石晶洞，打算祝贺她女儿出生并感谢她。礼物最终未能送出，由佩利佩长期保存。可以确认的是照护倡议和具体帮助已经发生，原文没有说明她提出的法案后来是否按原案通过。","people":["锡兰","赫尔曼"],"refs":[{"label":"火山旅梦·SL-6 · 行动后 林中小木屋","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act27side/level_act27side_06_end.txt","evidence":"game"},{"label":"火山旅梦·SL-7 · 行动前 靠着我的肩膀哭泣","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act27side/level_act27side_07_beg.txt","evidence":"game"}]},{"id":"siesta-tourism-transition","period":"禁采与旅游业逐步成为支柱的时期","title":"产业转型与黑曜石音乐节","body":"随着过度开采对环境的破坏逐渐受到重视，市政厅禁止继续开采黑曜石，但没有一并禁止已有矿石交易。城市转而利用火山、沙滩和夏季气候发展旅游业，旅馆、餐饮、纪念品贸易与演出活动扩大。旧矿工并没有因此全部得到适合的新职位；部分人后来仍会返回矿区私采，说明禁采和产业转换并未同步解决所有人的收入问题。\n\n黑曜石音乐节的起点比后来的大型舞台简陋得多。老居民回忆，第一次活动就在矿坑里，由一群工人随手弹奏、唱自己编的歌，没有像样的职业乐手。此后音乐节逐渐吸引外地游客与艺人，演变为延续半个月、分布于多条街道和公共广场的城市节庆。摇滚、爵士与说唱分别拥有演出空间，游客也能摆摊或参加表演。矿工娱乐由此成为城市文化和旅游生意的重要组成部分。","people":["苍苔","锡兰"],"refs":[{"label":"火山旅梦·SL-2 · 行动前 小蓝孩","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act27side/level_act27side_02_beg.txt","evidence":"game"},{"label":"火山旅梦·SL-6 · 行动后 林中小木屋","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act27side/level_act27side_06_end.txt","evidence":"game"},{"label":"火山旅梦·SL-8 · 行动前 爱之歌","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act27side/level_act27side_08_beg.txt","evidence":"game"},{"label":"火蓝之心·OF-ST1 · 幕间 摇滚起来","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act3d0/level_act3d0_st01.txt","evidence":"game"}]},{"id":"siesta-municipal-order","period":"《火蓝之心》开始以前","title":"市政经营与火山监测体系","body":"城市扩张过程中，赫尔曼通过市政体系经营汐斯塔，同时处理哥伦比亚和维多利亚带来的外交压力。他的妻子来自维多利亚，而维多利亚一度被当地人视为意图吞并城市的敌人，因而他曾不敢公开她的出身。芭芭拉继续以学者和矿工照护者的方式参与城市生活，两人的工作并不是同一条行政路径。后来回顾往事时，赫尔曼仍强调城市应由汐斯塔人自己决定走向。\n\n旅游业兴盛后，市政厅已有火山观测站及天灾信使等专业岗位，城市宣传却倾向于强调火山的安全和馈赠。黑曜石能够抑制矿石病的说法也进入广播，但阿米娅明确指出，医学上并没有相应依据。锡兰归来前后，官方观测与她掌握的样本之间开始出现矛盾。这里形成了《火蓝之心》的起点：城市已经拥有检测机构、成熟旅游市场和节庆组织能力，却仍须面对科学判断、商业利益与居民安全之间的分歧。","people":["赫尔曼","锡兰","阿米娅"],"refs":[{"label":"火山旅梦·SL-7 · 行动后 靠着我的肩膀哭泣","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act27side/level_act27side_07_end.txt","evidence":"game"},{"label":"火蓝之心·OF-ST1 · 幕间 摇滚起来","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act3d0/level_act3d0_st01.txt","evidence":"game"}]}]},"sami":{"id":"sami","intro":"萨米没有在所读游戏材料中呈现一条统一王朝的建国年表。其较早的社会记忆保存在族树、树谱、木刻历史和萨满传承之中；山地、林地与泽地又因环境和外部压力形成不同生活方式。北方灾异、邻国军队和南部贸易逐步改变了部族的迁徙与联系。","scope":"以部族共同体、传承制度、北地防线和南部交流为前史，衔接寒檀离乡及后续科考行程，不重复麦哲伦的当代旅途与葬礼救援。","chronologyNote":"原初森林和祖灵之父的称谓属于当地传统，不据此推算建国年代。部族制度、长期边防与近代贸易的起点多无绝对年，按发展层次叙述；集成战略的可变路线、遭遇和结局均不写成共同历史。","periods":[{"id":"sami-forest-and-ancestral-trees","period":"无明确纪年的部族起源记忆","title":"原初森林与族树共同体","body":"萨米人把原初森林称为这片土地的心脏，也是自身的来处与去处。祖灵之父萨米、安玛及大地意志等称谓，贯穿他们解释生存、狩猎与庇护的传统。这里的“萨米”不只表示外来地图划出的一块地方，还指向人与自然相处的秩序；这些信仰表达没有同时提供一个由君主宣布国家成立的时间。\n\n林地部族通常拥有族树。它是共同体中最年长、最受尊敬的存在，祖屋、居所和仪式围绕大树组织，外乡人不能随意触碰。长期定居的部族会把父辈、祖父辈以来的记忆与大树联系，族树缺失则被理解为族群过于年轻，或传承已经遭到重大破坏。居住地因而既是物质住所，也是社会身份与历史的载体，迁徙也不只是搬走行李，而涉及如何延续人与族树的关系。","people":["寒檀","提丰"],"refs":[{"label":"眠于树影之中·幕间 树影幢幢","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act15mini/level_act15mini_st03.txt","evidence":"game"},{"label":"眠于树影之中·幕间 自然的启示","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act15mini/level_act15mini_st04.txt","evidence":"game"}]},{"id":"sami-shamanic-transmission","period":"部族传承与地方权威长期形成以后","title":"树谱、萨满与雪祀制度","body":"萨米部族并非没有文字历史。传说与族史刻在木板上，完整的一部部族历史可以堆满数间树屋；树谱还保存与祖先、大树沟通及举行仪式所需的知识。长期安宁也可能使传承只剩象征，有的萨满已经无法完全理解祖传词句，必须寻求其他人的帮助。不同部族因此各有自己的历史保存方式，并不共享一本完整的中央编年史。\n\n萨满负责理解密文、解释征兆并照顾族人。雪祀则是更有能力和权威的首席萨满，可以理解为地方首领，并不必然是最年长者。学徒通过师承、巡游和试炼学习如何回应萨米的意志。相同符号随时间与人物变化可以具有不同意义，不能脱离具体情境机械翻译。这样的制度把知识解释、地方治理和应对灾害结合起来，也使传承中断直接影响部族决定是否迁移的能力。","people":["寒檀","提丰"],"refs":[{"label":"眠于树影之中·幕间 树影幢幢","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act15mini/level_act15mini_st03.txt","evidence":"game"},{"label":"眠于树影之中·幕间 自然的启示","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act15mini/level_act15mini_st04.txt","evidence":"game"}]},{"id":"sami-northern-frontier","period":"北方灾异长期侵袭与边防形成时期","title":"北地防线与环境分流","body":"按当地人的划分，最北群山中的居民为山地人，中部森林及附近为林地人，南方沼泽聚落则为泽地人。区别不仅在住处：北方战士长期巡逻、狩猎与作战，既对付冰原灾异，也防备乌萨斯来人；林地物产和定居条件较好，泽地又更频繁地参与南方贸易。不同处境形成各自的待客习惯、戒备程度和生活需要，不能用单一的“原始部族”形象概括。\n\n北地战士修筑堡垒、高墙和关隘，以侦测法术监控通道。防线既拦住向南侵入的威胁，也限制人和野兽贸然进入冰原，避免污染随返程者流入聚落。过去连阵亡者遗物都带回的做法，也因遗物可能残留污秽而改变。灾异的认识与防御经验在日常损失中积累，不能简化成对外乡人的无由敌意；部族南迁则使前线与后方之间持续产生不同选择。","people":["提丰","寒檀","埃克提尔尼尔"],"refs":[{"label":"眠于树影之中·幕间 冰原的女儿","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act15mini/level_act15mini_st02.txt","evidence":"game"},{"label":"眠于树影之中·幕间 树影幢幢","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act15mini/level_act15mini_st03.txt","evidence":"game"}]},{"id":"sami-southern-exchanges","period":"近代贸易与外来探索逐渐扩大时期","title":"南部贸易与外来机构进入","body":"萨米与外界并非始终断绝来往。药用原材料是与哥伦比亚的重要贸易品，外来药物中的若干成分也来自当地植物。乌萨斯商队定期经过部分部族市集，能够使用多种语言的萨满和向导承担沟通工作。到南部泽地，因交易需要而设置的通讯设备更多，最南端的察帕特则聚集哥伦比亚公司的办事处，形成与北地关隘截然不同的接触环境。\n\n外来贸易、旅游和科考也带来新的冲突。有人以“原始”“野蛮”的想象购买旅行体验，却不理解捕食、死亡和遗体处置在当地生活中的位置；科考机构希望开辟进入冰原的道路，萨米人则必须考虑来客是否会携回污染。乌萨斯的军事压力又进一步削弱北方居民对陌生人的信任。正是在原有部族制度、长期防御与不均衡交流交织的背景下，寒檀的离乡、南迁者的选择和后来的搜救科考才逐步发生。","people":["寒檀","提丰","麦哲伦"],"refs":[{"label":"眠于树影之中·幕间 冰原的女儿","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act15mini/level_act15mini_st02.txt","evidence":"game"},{"label":"眠于树影之中·幕间 树影幢幢","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act15mini/level_act15mini_st03.txt","evidence":"game"},{"label":"眠于树影之中·幕间 自然的启示","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act15mini/level_act15mini_st04.txt","evidence":"game"}]}]},"durin":{"id":"durin","intro":"这里的“杜林”首先指地下族群及其分散城市，不是一座有统一开国年和首都的国家。游戏可追述的建制以横向城市网络、矿业运输与公共协商为基础；际崖城则由追求美与和谐的设计师建立，经过工程、设计流派和生活选择逐步形成《理想城》开篇时的面貌。","scope":"先交代地下城市社会与际崖城的建立，再写矿业交通、灾害传统和建筑师传承，止于地面访客进入之前；撤离工程与迁入阿卡胡拉由现有纪事承接。","chronologyNote":"原文没有公开整个族群最初进入地下或际崖城建成的确切年代，不据“自古”推定年数。升降梯起源的一种解释明确归于杜林历史学家；半年前地震、八年前斯第奇获救均以《理想城》为相对时点。","absorbedPhases":{"durin-city":[0]},"periods":[{"id":"durin-underground-networks","period":"无确切纪年的地下城市发展阶段","title":"分散城市与横向探索","body":"杜林社会由多座地下城市组成，不能把际崖城的经历等同于整个族群的起源。探险者的测算认为，多数城市位于地表以下约一千至一千五百米，地下探索通常沿水平方向展开，很少在同一处上下叠起相邻城市。城市无法像地表移动城那样整体避灾，因此需要考虑与其他聚落的通道和撤离条件。\n\n列车是这种城市网络中最常见的交通工具，隧道连接生活、资源开采和城市间往来。地下并不意味着与地表完全断绝：有人借工业升降梯进行冒险，返回后将见闻与地图写成游记，保存在城市图书馆。只是多数居民对上陆兴趣不大，地面人也很少准确了解地下。早期接触因个人探险和偶然通路而零散发生，并没有在所读原文中构成一次全族共同迁出的历史。","people":["鸿雪","至简"],"refs":[{"label":"理想城：长夏狂欢季·IC-1 · 行动前 沉浸式游览","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act20side/level_act20side_01_beg.txt","evidence":"game"},{"label":"理想城：长夏狂欢季·IC-6 · 行动后 战逃反应","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act20side/level_act20side_06_end.txt","evidence":"game"}]},{"id":"durin-zeruertza-foundation","period":"际崖城建立与公共生活形成时期","title":"设计师建城与公共协商","body":"按斯第奇对来客的介绍，际崖城是一群建筑设计前辈为创造美与和谐的生活而建立的城市，在杜林聚落中也具有自己的特色。人工穹顶模拟日照，居住建筑、绿化、商业设施和公共空间共同构成生活环境。建立城市不仅意味着挖出洞穴，也需要把结构、能源、环境和人的日常需要组合起来。\n\n城市规划由许多人共同决定，专业代表和普通居民都能影响资源去向。建筑师不能只凭个人才华便让全城照图施工，方案还须被解释、讨论并得到认可。来自地表的阿芙朵嘉后来能以文学代表的身份参与城市事务，也说明际崖城的公共角色并不只由最初的设计师及其后代独占。这里没有一位负责替所有人作出选择的固定城市君主，专业意见与共同决定之间的关系长期存在。","people":["至简","鸿雪"],"refs":[{"label":"理想城：长夏狂欢季·IC-1 · 行动前 沉浸式游览","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act20side/level_act20side_01_beg.txt","evidence":"game"},{"label":"理想城：长夏狂欢季·IC-6 · 行动后 战逃反应","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act20side/level_act20side_06_end.txt","evidence":"game"},{"label":"理想城：长夏狂欢季·IC-8 · 行动前 金属气味","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act20side/level_act20side_08_beg.txt","evidence":"game"}]},{"id":"durin-mining-infrastructure","period":"矿业运输与工业设施逐渐扩展时期","title":"矿脉开发与升降设施","body":"杜林人对矿物探索的热情，使交通设施并不只沿城市网络横向伸展。个人挖掘可以进入聚落上下数百米处，遇到值得开采的矿层后，才需要把运输问题带入公共工程讨论。有些杜林历史学家因此认为，最初的升降梯来自某位工业代表发现城上矿脉后提出的直接运输方案；这是一种有明确归属的历史解释，而非原文已经展示的发明现场。\n\n际崖城自己的升降梯则有较具体的来历。上方发现矿脉后，居民表决建造工业升降设施，并预留扩建空间；后来找到更近的矿源，原设施便闲置。探险者又把它当作抵达地表的捷径。原本服务矿业的坚固结构因此留下了其他用途，但这并不表示它从建造之初就是全城人口撤离工程。工业需求、公共表决与后来的个人使用，是几个不同阶段。","people":["至简","鸿雪","极境"],"refs":[{"label":"理想城：长夏狂欢季·IC-6 · 行动后 战逃反应","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act20side/level_act20side_06_end.txt","evidence":"game"}]},{"id":"durin-disaster-and-rebuilding","period":"地下城市反复迁移形成的长期传统","title":"灾害预警与城市重建","body":"固定城市面临活化源石矿脉带来的威胁。杜林聚落通常配备检测设施，发现矿脉蔓延后提前预警；它只针对这一类地下风险，不能等同于天灾信使的全部工作。居民习惯在危险扩大前迁走，也习惯带着工业装备及机器人，在其他地方重新建城。克罗绮说明，保存关键设备后，重建可以在数月内推进，这种生产能力是其生活选择的重要条件。\n\n长期迁移又形成了为旧城保留最后面貌的惯例。居民并非不悲伤，也不是不珍惜家园，而是希望后来返回的同胞或子孙在遗迹中看见生活、技术和审美的成果，而不只看见灾难。临行前修整城市因此有了公共意义。它同撤离行动属于两个相关却不同的目标：人和必要设备必须获得生路，已经无法挽救的建筑则尽可能以居民决定的形式留下。","people":["鸿雪","至简"],"refs":[{"label":"理想城：长夏狂欢季·IC-7 · 行动前 生活之道","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act20side/level_act20side_07_beg.txt","evidence":"game"}]},{"id":"durin-finch-school-and-quake","period":"斯第奇获救至地面访客抵达以前","title":"建筑师传承与穹顶争议","body":"八年前，斯第奇在活性源石矿脉爆发中失去家园并感染，芬奇将他带在身边，教授建筑设计，他也改用老师的姓氏。芬奇反对繁复装饰和不断扩大的欲望，设计风格虽然不同于流行趣味，却能通过解释获得居民支持。斯第奇继承技艺后更强调有限生命与资源的实际用途，对仅为城市迎接毁灭而投入大量工程尤其难以认同。\n\n芬奇离开前给他留下课题：以自己的穹顶设计说服全城。之后的方案屡遭否决，斯第奇逐渐不再参加设计部会议；卡奇继任设计代表，仍希望改造芬奇留下的穹顶。约半年前地震又破坏穹顶，水流形成瀑布，大滑梯随之建成，城市选择优先享受新设施。设计师的理念分歧、沟通受挫和公共工程取舍由此积累，后来才引出上陆求助与地面来客进入际崖城的故事。","people":["至简","鸿雪"],"refs":[{"label":"理想城：长夏狂欢季·IC-7 · 行动前 生活之道","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act20side/level_act20side_07_beg.txt","evidence":"game"},{"label":"理想城：长夏狂欢季·IC-8 · 行动前 金属气味","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act20side/level_act20side_08_beg.txt","evidence":"game"},{"label":"理想城：长夏狂欢季·IC-3 · 行动前 奇谈怪论","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act20side/level_act20side_03_beg.txt","evidence":"game"},{"label":"理想城：长夏狂欢季·IC-2 · 行动前 下坠","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act20side/level_act20side_02_beg.txt","evidence":"game"},{"label":"理想城：长夏狂欢季·IC-3 · 行动后 奇谈怪论","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act20side/level_act20side_03_end.txt","evidence":"game"}]}]},"minos":{"id":"minos","intro":"米诺斯的起源叙述围绕克瑞斯拉安置难民、建立第一神殿展开，之后才有雅赛努斯及众多城邦。城邦长期共享英雄故事和祭司传统，萨尔贡占领又使它们经历毁城、强征劳工和移动城市改造；百余年抵抗后的停战，才为当代重建创造条件。","scope":"从建国传统、城邦秩序写至《雅赛努斯复仇记》开始前的停战与行政改革，不重述古琴交换、舞台冲突及后续公投。","chronologyNote":"克瑞斯拉事迹作为当地传承的起源叙述保留，所读原文未给确切建国年。最后大型战役在篇章开始五年前、理事官职位新设于两年前，均为剧情明确相对时间，不换算绝对年份。","periods":[{"id":"minos-first-sanctuary","period":"无明确纪年的起源传统","title":"难民安置与第一神殿","body":"雅赛努斯的官方讲述把米诺斯的起点放在克瑞斯拉身上：她带领不同族群的难民离开战争与瘟疫，将他们安置在四面环山的花园中。追随者随后共同建设住处和第一座神殿。按这一叙述，宗教与公共生活的中心先于后来城市形成，雅赛努斯由此发展为最早的城邦，米诺斯也逐渐成为众多城邦共存的地区。\n\n这一传统没有把所有居民归为单一种族，也没有把地区写成自始便由一个王室统一管理的疆域。共同体首先建立在避难、定居和共享英雄故事的过程上，神殿则成为保存这些故事、举行仪式的场所。克瑞斯拉因而既是地方城市史中的奠基者，也是整个米诺斯认同的重要人物；其竖琴与第一神殿后来受到重视，正来自这层建制记忆。","people":["克瑞斯拉","帕拉斯"],"refs":[{"label":"雅赛努斯复仇记·ME-ST-1 · 幕间 涉过流淌的河","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act48side/level_act48side_st01.txt","evidence":"game"}]},{"id":"minos-civic-tradition","period":"城邦秩序长期形成的时期","title":"英雄崇拜与城邦公共生活","body":"米诺斯各城邦并非只有相同的建筑或祭礼，而是共同传唱英雄故事，以此解释勇气、责任和公共生活。祭司主持仪式、解释神谕，也参与城市事务的协调；戏剧、辩论和节庆则让普通居民能够不断重述这些传统。各城之间保持区别，村落也仍分散在移动城市以外，居民通过道路、河流和知识传授发生联系。\n\n英雄崇拜又形成了排斥感染者的惯例。没有史诗提到英雄感染、雕像也没有源石结晶，便被一些人当作矿石病会隔绝英雄气概的依据。这种判断影响祭司培养、家族继承和个人生活。调香师感染后离乡、帕拉斯不能继续保有原来祭司地位，都发生在这套传统仍有实际约束力的社会中；共同文化既维系城邦，也会规定谁能够获得承认。","people":["帕拉斯","调香师","赞索斯"],"refs":[{"label":"雅赛努斯复仇记·ME-7 · 行动后 奔袭","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act48side/level_act48side_07_end.txt","evidence":"game"},{"label":"雅赛努斯复仇记·ME-8 · 行动后 神谕示显","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act48side/level_act48side_08_end.txt","evidence":"game"}]},{"id":"minos-colonial-reconstruction","period":"萨尔贡占领与三城建设时期","title":"玛拉统治与移动城市改造","body":"萨尔贡侵入后，玛拉帕夏推行大规模改造。米诺斯人的回忆记载，她焚毁三城以外的城邦，关闭神殿、取缔戏剧，并安排萨尔贡人迁入，试图改变当地文化。雅赛努斯、科林尼亚与拉刻代蒙被搬上移动平台。萨尔贡的旅行文字则把工程描述为保存城市风景的功绩，尤其赞扬雅赛努斯仍有群山与河流的外观。\n\n移动平台的技术建设并非只由征服者完成。伊萨科斯家族传承的工程记忆指出，技术熟练的米诺斯人曾被强征，参与动力层等设施施工；工程师还要登记建材、人力配置、工人姓名及被征发的来源。战争中的文化压制与劳工剥削，因此和后来仍在使用的城市基础设施同时存在。所谓三城建设资料，也不只是能够与政治历史分开的纯技术图纸。","people":["赞索斯","缇缇"],"refs":[{"label":"雅赛努斯复仇记·ME-ST-1 · 幕间 涉过流淌的河","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act48side/level_act48side_st01.txt","evidence":"game"},{"label":"雅赛努斯复仇记·ME-6 · 行动后 旧日诗篇","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act48side/level_act48side_06_end.txt","evidence":"game"}]},{"id":"minos-resistance-ceasefire","period":"持续百余年的抵抗至篇章开始五年前","title":"游击抵抗与边境停战","body":"面对占领和侵扰，村落与城邦出身者进入山地游击队。战士缺乏物资，将武器、护甲和粮食集中后依任务分配；同一件装备会在伤亡之后反复转到其他人手中。来自雅赛努斯的伊萨科斯曾将移动城市技术带入沼地村落，帮助建屋、开田和抵御寒灾，之后又前往战场。赞索斯寻找他的过程中加入游击队，逐渐接触到不同故乡的战士。\n\n这一时期的抵抗延续了一百多年。直到当代篇章开始五年前，最后一场大型边境战役结束，双方才正式约定互不侵犯。停战保住了生者继续生活的机会，却没有立即恢复被破坏的河流、土地和家庭。边境村落仍会面对零星侵袭；帕拉斯等人另行促成的地方互不侵犯安排，也不能与两国层面的停战完全混为一谈。","people":["赞索斯","帕拉斯"],"refs":[{"label":"雅赛努斯复仇记·ME-ST-1 · 幕间 涉过流淌的河","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act48side/level_act48side_st01.txt","evidence":"game"},{"label":"雅赛努斯复仇记·ME-6 · 行动后 旧日诗篇","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act48side/level_act48side_06_end.txt","evidence":"game"},{"label":"雅赛努斯复仇记·ME-8 · 行动后 神谕示显","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act48side/level_act48side_08_end.txt","evidence":"game"}]},{"id":"minos-postwar-administration","period":"停战后至当代篇章开始以前","title":"行政改革与文化重建准备","body":"战争告终后，雅赛努斯继续依赖祭司、议事厅及公共表决处理事务。传统流程能够维持认可，却也使跨机构申请和公共工程推进缓慢。两年前设置理事官职位，原意是替神殿祭司分担事务、简化流程，里底娅由此获得安排城市工作的空间。她支持罗德岛设立办事处，也推动以现代项目管理方式处理工程验收。\n\n第一神殿的旧址早已毁于战火，居民自发筹备重建，以恢复共同记忆的中心。城市需要调配采石、运输与果农出货等相互竞争的需求，文化恢复因此始终牵涉具体的资源分配。到篇章开始那年，米诺斯与萨尔贡才正式建交。停战、行政调整和神殿重建各有不同起点，合在一起构成了后续文物归还与历史责任争论得以公开发生的条件。","people":["里底娅","帕拉斯","调香师"],"refs":[{"label":"雅赛努斯复仇记·ME-ST-1 · 幕间 涉过流淌的河","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act48side/level_act48side_st01.txt","evidence":"game"},{"label":"雅赛努斯复仇记·ME-7 · 行动后 奔袭","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act48side/level_act48side_07_end.txt","evidence":"game"}]}],"absorbedPhases":{"minos-heroes":[0,1]}},"kazimierz":{"id":"kazimierz","intro":"卡西米尔的骑士竞技，建立在更早的政权更替与社会变迁之上。神民的统治被骑士推翻以后，土地、家族与军事义务构成骑士秩序；近代管理领产的扈从逐步积累财富，最终发展为能够左右国家生活的财阀。了解这段过程，才能看清临光家族、商业联合会与感染者骑士各自在争取什么。","scope":"瑕光干员档案中的制度史、《长夜临光》对天马退位、可汗传统、历届冠军与感染者赛制的回顾。","chronologyNote":"早期政权更替未采用未核实的建国年份；“约一百二十年前”以瑕光档案的叙述时点为基准，未直接换算成年号。“六年前”“三年前”以本届特锦赛为参照。这里只还原材料可以支持的先后，不补写完整王朝世系。","periods":[{"id":"pegasian-rule","period":"骑士政权建立以前，确切纪年未核","title":"神民统治与天马王权","body":"在现代骑士竞技出现之前，卡西米尔经历过由神民统治的时代。瑕光的档案把骑士推翻神民、建立骑士团制度，列为这个国家的第一次重大历史转折。《长夜临光》中，逐魇骑士也明确将天马退位与此后的“骑士之国”相连。今天临光家族的天马身份因而不能直接等同于旧王权的延续：同一族群仍生活在这个国家，统治结构却已经改变。\n\n旧时代的征服记忆并未随政权消失而完全断裂。逐魇骑士以可汗的誓言和功绩理解骑士之路，其他人物则指出，那段历史早已过去上千年。他在当代赛场上寻找对手，是古老传统在后世的回响，不能反过来把他的参赛时间当成古代战争的年代。本篇从可考的神民统治讲起，关于最初统治者如何统一各地、王室的完整世系和确切开国年份，现有采用材料不足以连续复原。","people":[],"refs":[{"label":"瑕光·档案资料三：骑士推翻神民统治","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/excel/handbook_info_table.json","evidence":"game","note":"瑕光 char_423_blemsh 对应档案栏目；原文由公开游戏数据镜像提供。"},{"label":"《长夜临光》NL-2 行动后：天马退位的回顾","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act13side/level_act13side_02_end.txt","evidence":"game"},{"label":"《长夜临光》NL-9 行动前：可汗历史的时距","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act13side/level_act13side_09_beg.txt","evidence":"game"}]},{"id":"knightly-order","period":"神民统治结束以后","title":"骑士团制度与贵族统治","body":"神民统治被推翻后，骑士不再只是为某位统治者效力的武装力量，而成为掌握政治身份的阶层。骑士团制度与骑士专政取代旧秩序，骑士家族以领地、家业和封号维持其地位。家族既需要有人承担骑士身份，也需要有人管理财产、生产和人员；在这套分工中，扈从与扈从团逐渐接手领产经营。\n\n这不是一个只靠个人武艺便能运转的社会。土地要持续创造收入，堡垒和后来出现的移动平台需要投入，边境冲突也要求长期供应。贵族可以拥有名号和军事声望，却未必掌握经营财富的能力。瑕光档案记载的国民院财产拍卖，说明在近代巨变发生以前，贵族的地产与城堡已经进入可由公共机构主持处置的法律程序。后来扈从能够合法购买主人的家产，正是从这个制度内部发生的变化。\n\n原作将这段骑士建制与之后的财阀崛起分为两个历史转折。本篇据此区分先后，未把监正会、国民院和骑士协会在现代承担的全部职能，都倒推为它们在建制之初便已具备的制度。","people":[],"refs":[{"label":"瑕光·档案资料三：骑士专政、扈从经营与国民院拍卖","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/excel/handbook_info_table.json","evidence":"game","note":"瑕光 char_423_blemsh 对应档案栏目；原文由公开游戏数据镜像提供。"}]},{"id":"squire-auction","period":"距瑕光档案叙述时点约一百二十年前","title":"扈从购堡与财富关系变化","body":"在移动城邦尚未像后来那样发达时，一位领土较广的贵族骑士去世，由于没有子嗣，国民院拍卖了他位于小型移动平台上的城堡与大片土地。拍卖本身并不罕见，真正使此事成为历史记忆的，是最终提出最高价格的人：他不是另一名贵族的代表，而是这位骑士原来的扈从。\n\n扈从的报价令在场贵族震动，国民院事后又确认，购置财产的资金全部来自合法收入。这意味着财富已经不再只沿贵族头衔和血缘流动。长期替骑士管理家业的人，能够凭借经营所得购买过去由主人占有的土地与居所。名义上的服侍关系还在，双方支配的经济资源却已经出现逆转。\n\n档案以这一事件说明扈从阶层的变化，并未说某一次拍卖便立即建立了商业联合会。真正改变国家的，是此后持续数十年的积累：商人和扈从进一步结成联系，骑士贵族在对外摩擦和彼此竞争中，越来越依赖掌握财产与经营网络的旧部。原本被置于骑士之下的经济活动，开始反过来制约骑士能够采取的行动。","people":[],"refs":[{"label":"瑕光·档案资料三：约一百二十年前的城堡拍卖及其后数十年","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/excel/handbook_info_table.json","evidence":"game","note":"瑕光 char_423_blemsh 对应档案栏目；原文由公开游戏数据镜像提供。"}]},{"id":"commercial-reordering","period":"购堡事件之后的数十年及近代制度重组","title":"财阀崛起与骑士身份重组","body":"财富的转移随后变成了更深的社会变革。卡西米尔与乌萨斯、莱塔尼亚之间的频繁摩擦，以及大贵族之间的竞争，使骑士不得不依靠富有的扈从维持地位。随着企业承担城邦建设、国土防护和居民生活所需的生产与流通，旧扈从阶层逐渐成为寡头财阀。现代商业联合会的力量，应当放在这段长期变化中理解，而非看成几位商人在某届比赛期间突然夺权。\n\n这一过程并不平和。档案明确记载了延续数十年的残酷变革，并把现代竞技骑士制度视作其结果。负责守卫边疆的征战骑士失去贵族这一政治身份，转为监正会直属的军事力量；贵族骑士以及符合当时资格规则的公民，则可以通过竞技取得封号和贵族资格。古代骑士之间的技艺切磋，由此发展为经济、政治与文化共同围绕的行业。\n\n骑士称号于是出现了不同的实际含义：边防作战的责任、家族的传统声望、竞技授予的资格，以及企业能够经营的公众形象，不再始终重合。临光家族后来面临的长骑继任问题，玛恩纳对现代贵族身份的拒绝，以及联合会对竞技骑士的控制，都发生在这套已改变的规则之中。","people":["玛恩纳"],"refs":[{"label":"瑕光·档案资料三：扈从财阀化与征战、竞技骑士的制度区分","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/excel/handbook_info_table.json","evidence":"game","note":"瑕光 char_423_blemsh 对应档案栏目；原文由公开游戏数据镜像提供。"},{"label":"《长夜临光》NL-ST-2《权与力》：资本与骑士的关系","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act13side/level_act13side_st02.txt","evidence":"game"}]},{"id":"radiant-exile","period":"本届特锦赛约六年前及流放之后","title":"耀骑士夺冠与临光家族危机","body":"到玛嘉烈走上竞技场时，临光家族已经积累了百余年的骑士声望。家族的先人曾参与边境守卫与跨国斗争，玛嘉烈又以竞技冠军的身份延续了其名望。然而，她的夺冠并没有消除传统骑士与商业秩序之间的冲突。她随后被认定隐瞒感染者身份，遭到流放；本届特锦赛的公开播报回顾此事时，明确称其发生在六年前。\n\n流放使她离开故乡，也使家族的荣耀失去最受公众瞩目的承载者。此后，年长的家族长骑去世，玛恩纳拒绝以成为竞技骑士的方式接过责任，临光家逐渐陷入没有长骑维系资格的处境。这几件事具有明确的因果联系，但档案没有为每个环节都给出同一精度的年月；不能把长骑逝世与叔父拒任，也全部压在流放发生的那一年。\n\n玛莉娅后来参赛，首先要回应的正是这场家族危机。她从姐姐、姑母和老骑士那里继承了对于骑士的理解，却必须在以商业化竞技维持身份的制度中争取家族位置。她的故事因此并非卡西米尔历史的开端，而是此前国家制度和家族经历共同作用的结果。","people":["临光","瑕光","玛恩纳","鞭刃"],"refs":[{"label":"瑕光·档案资料二：临光家百余年声望与长骑危机","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/excel/handbook_info_table.json","evidence":"game","note":"瑕光 char_423_blemsh 对应档案栏目；原文由公开游戏数据镜像提供。"},{"label":"《长夜临光》NL-10 行动后：六年前的流放回顾","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act13side/level_act13side_10_end.txt","evidence":"game"}]},{"id":"infected-competition","period":"本届特锦赛约三年前至本届参赛以前","title":"血骑士夺冠与感染者赛制建立","body":"耀骑士离乡以后，感染者骑士的处境又因血骑士而发生变化。《长夜临光》回顾，感染者狄开俄波利斯曾在三年前夺冠。马克维茨则明确说明，现行感染者骑士制度，是在血骑士夺冠后，由监正会与商业联合会常务董事共同决定的新赛制。感染者由此获得了一条以竞技谋生、争取身份的正式通道。\n\n开放参赛并不意味着处境立即平等。焰尾的档案记载，索娜失去故乡、感染矿石病后，先靠底层工作维持生活，后来才得知感染者竞技这条出路。她最初面对的不是电视转播中的光鲜赛事，而是猛兽、陷阱与封闭环境。能够参赛，与能否获得安全、治疗和公平对待，仍是不同的问题。\n\n在这样的制度背景下，感染者骑士开始结伴寻求生存，红松骑士团逐渐形成；另一边，玛莉娅为保存家族资格进入同一套竞技体系。两条人物线将在本届大赛前后相交。以下正文才进入她们具体的相识、参赛和协同行动，继而讲述玛嘉烈归来与本届特锦赛。","people":["焰尾","灰毫","瑕光","临光"],"refs":[{"label":"《长夜临光》NL-3 行动前：感染者骑士赛制的制定","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act13side/level_act13side_03_beg.txt","evidence":"game"},{"label":"《长夜临光》NL-7 行动后：三年前的血骑士冠军","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/story/activities/act13side/level_act13side_07_end.txt","evidence":"game"},{"label":"焰尾·档案资料二：感染后的生计与竞技经历","url":"https://github.com/Kengxxiao/ArknightsGameData/blob/63c7cec73c3858d0ae913f85cc89af3cef4d744f/zh_CN/gamedata/excel/handbook_info_table.json","evidence":"game"}]}]}},"meta":{"regions":22,"periods":95,"characters":29295,"sources":143,"date":"2026-11-04","revision":"regional-origins-20261104","style":"从最早可考的起源与建制写起，再接近现代事件；明确相对年代、传统记述与资料未明处。"}};
for(const s of window.TERRA.stories){const o=window.REGIONAL_ORIGINS.regions[s.region];if(!o)continue;s.origins=o;s.modernIntro=s.intro;s.intro=o.intro;s.scope=o.scope+'；后续事件：'+s.scope;}
